    /// Application sur un dossier temporaire de 3 JPEG, avec un cache temporaire.
    fn harness() -> (Harness<'static, TriApp>, tempfile::TempDir) {
        harness_with(64, 48)
    }

    /// Application sur 3 JPEG de `w`×`h` pixels, avec un cache temporaire.
    fn harness_with(w: u32, h: u32) -> (Harness<'static, TriApp>, tempfile::TempDir) {
        harness_files(&["img0.jpg", "img1.jpg", "img2.jpg"], w, h)
    }

    /// Application sur les images `names` (JPEG ou PNG selon l'extension) de `w`×`h`
    /// pixels, avec un cache temporaire.
    fn harness_files(
        names: &[&str],
        w: u32,
        h: u32,
    ) -> (Harness<'static, TriApp>, tempfile::TempDir) {
        let images = names
            .iter()
            .enumerate()
            .map(|(i, name)| {
                let pixel = image::Rgb([((40 * i) % 256) as u8, 100, 160]);
                (*name, image::RgbImage::from_pixel(w, h, pixel))
            })
            .collect();
        harness_images(images)
    }

    /// Application sur les images `images` (nom, pixels), avec un cache temporaire.
    fn harness_images(
        images: Vec<(&str, image::RgbImage)>,
    ) -> (Harness<'static, TriApp>, tempfile::TempDir) {
        let dir = tempfile::tempdir().unwrap();
        let photos = dir.path().join("photos");
        std::fs::create_dir(&photos).unwrap();
        for (name, img) in &images {
            img.save(photos.join(name)).unwrap();
        }
        let mut settings = AppSettings::default();
        settings.cache.dir = Some(dir.path().join("cache"));
        // Pas de surveillance des volumes : les tests fixent leur propre arborescence.
        settings.places.watch_ms = 0;
        // Ni du dossier ouvert (un test l'active pour lui seul).
        settings.watch.interval_ms = 0;
        // Séquences (`f °`, `gg`) : délai large, sinon une machine chargée (tests en
        // parallèle) le dépasse entre deux touches et le test échoue au hasard.
        settings.gui.key_sequence_timeout_ms = 60_000;
        // `y` seul (copier) agit dès l'image suivante, sans attendre un éventuel `y w`.
        settings.gui.key_ambiguous_timeout_ms = 0;
        // Les deux jeux de raccourcis : les tests tapent l'un et l'autre.
        settings.gui.profile = crate::actions::Profile::Classic;
        // Ni darktable, ni RapidRAW, ni RawTherapee, ni ART dans les tests (installés ou
        // non sur la machine : RawTherapee et ART le sont sur celle de développement
        // depuis le 31/10/2026, et leurs profils de notes se créaient d'eux-mêmes) : un
        // test les simule là où il le faut.
        settings.develop.darktable = String::new();
        settings.develop.rapidraw = String::new();
        settings.develop.rawtherapee = String::new();
        settings.develop.art = String::new();
        // Déchargements : historique et racine dans le dossier temporaire.
        settings.offload.history = dir.path().join("history.tsv").display().to_string();
        settings.offload.destination = dir.path().join("photos-local").display().to_string();
        // Jamais d'éjection réelle dans les tests : la « carte » est un dossier temporaire,
        // sur le disque du système.
        settings.offload.eject_after = false;
        // Données (dernier dossier…) dans le dossier temporaire : jamais celles de
        // l'utilisateur.
        settings.data.dir = Some(dir.path().join("data"));
        // Textes en français (les tests cherchent les libellés), quelle que soit la langue
        // du système.
        settings.i18n.language = tri::i18n::LanguageSetting::Fr;
        crate::i18n::init(settings.i18n.language);
        // Jamais la corbeille de l'utilisateur : suppression définitive, dans le dossier
        // temporaire.
        settings.files.trash = false;
        // Actions sur les fichiers autorisées (interdites par défaut) : les tests les
        // essaient ; un test vérifie le refus.
        settings.files.allow_actions = true;
        // Pas de piles : les images de test, des aplats de couleurs proches, seraient
        // groupées (le test des piles les active).
        settings.similarity.background = false;
        // Un réglage écrit pendant un test (bouton, case) : dans le dossier temporaire,
        // jamais la configuration de l'utilisateur (sans chemin, ce serait elle).
        let config = dir.path().join("config.toml");
        let mut harness = Harness::builder()
            .with_size(vec2(1000.0, 700.0))
            .build_eframe(move |_cc| {
                TriApp::new(Some(photos), settings, None).with_config(Some(config))
            });
        // Notes lues en fond (issue n° 15) : les tests partent, comme l'utilisateur après
        // un instant, d'un dossier dont les notes sont connues.
        run_until(&mut harness, |app| app.loading.is_none());
        (harness, dir)
    }

    /// Tape `key` avec `modifiers` comme la vraie fenêtre la livre (revue du 28/10/2026,
    /// après #194) : egui-winit remplace Ctrl+X / C / V (et sous Windows Maj+Suppr,
    /// Ctrl+Inser, Maj+Inser) par couper / copier / coller ; `egui_kittest`, lui, enverrait
    /// la touche elle-même, et un raccourci cassé passerait les tests.
    fn press(h: &mut Harness<'_, TriApp>, key: Key, modifiers: Modifiers) {
        // Ailleurs que sur macOS, « commande » est Ctrl.
        let modifiers = Modifiers {
            command: modifiers.command || (modifiers.ctrl && !cfg!(target_os = "macos")),
            ..modifiers
        };
        let events = crate::actions::winit_events(key, modifiers, cfg!(windows));
        if matches!(events.as_slice(), [UiEvent::Key { .. }, ..]) {
            h.key_press_modifiers(modifiers, key);
        } else {
            // Modificateurs tenus pendant l'image de l'événement, relâchés à la suivante
            // (comme au clavier : `event_modifiers` les relâcherait dans la même image).
            h.event(UiEvent::ModifiersChanged(modifiers));
            for event in events {
                h.event(event);
            }
            h.run_steps(1);
            h.event(UiEvent::ModifiersChanged(Modifiers::NONE));
        }
        h.run_steps(3);
    }

    /// Après le leader (Ctrl+B), les touches `keys`.
    fn leader(h: &mut Harness<'_, TriApp>, keys: &[(Key, Modifiers)]) {
        press(h, Key::B, Modifiers::CTRL);
        for &(key, modifiers) in keys {
            press(h, key, modifiers);
        }
    }

    /// Un caractère tapé (« ( », « = »…), lié pour lui-même quelle que soit la touche.
    fn type_text(h: &mut Harness<'_, TriApp>, text: &str) {
        h.event(UiEvent::Text(text.into()));
        h.run_steps(3);
    }

    /// Une action sans touche par défaut.
    fn act(h: &mut Harness<'_, TriApp>, action: Action) {
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, action);
        h.run_steps(3);
    }

    /// Le profil vim (les tests tournent en classique).
    fn use_vim(h: &mut Harness<'_, TriApp>) {
        h.state_mut().keymap =
            crate::actions::Keymap::from_profiles(&[crate::actions::Profile::Vim])
                .with_leader("Ctrl+b")
                .unwrap()
                .with_loupe(crate::settings::LoupeKey::Key(Key::M));
    }

    #[test]
    fn the_key_menu_holds_the_sequence_and_escape_cancels_it() {
        let (mut h, _dir) = harness();
        h.state_mut().gui.key_menu_delay_ms = 0;
        act(&mut h, Action::Open);
        assert_eq!(h.state().mode, Mode::View);
        leader(&mut h, &[]);
        assert!(h.state().sequencer.is_held(), "menu affiché");
        let held = h
            .state()
            .sequencer
            .prefix(Instant::now())
            .map(|(p, _)| p.len());
        assert_eq!(held, Some(1));
        // Échap abandonne la séquence sans quitter le plein écran.
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(!h.state().sequencer.is_held());
        assert_eq!(h.state().mode, Mode::View);
        // Désactivé : pas de menu.
        h.state_mut().gui.key_menu = false;
        leader(&mut h, &[]);
        assert!(!h.state().sequencer.is_held());
    }

    #[test]
    fn sort_by_one_key_keeps_the_direction() {
        use tri::sort::SortKey;
        let (mut h, _dir) = harness();
        act(&mut h, Action::SortBy(SortKey::Stars));
        assert_eq!(h.state().order.key, SortKey::Stars);
        act(&mut h, Action::SortReverse);
        let descending = h.state().order.descending;
        act(&mut h, Action::SortBy(SortKey::Name));
        assert_eq!(h.state().order.key, SortKey::Name);
        assert_eq!(h.state().order.descending, descending);
    }

    #[test]
    fn a_render_is_chosen_directly() {
        // Demandé le 07/11/2026 : un rendu précis depuis la palette, sans passer par les
        // autres.
        use crate::grid_render::GridRender;
        let (mut h, _dir) = harness();
        h.run_steps(3);
        act(&mut h, Action::Render(GridRender::LibRaw));
        assert_eq!(h.state().grid_render, GridRender::LibRaw);
        act(&mut h, Action::Render(GridRender::Embedded));
        assert_eq!(h.state().grid_render, GridRender::Embedded);
        // Un logiciel absent : refusé, avec la raison, rien ne change.
        h.state_mut().developers = Default::default();
        let darktable = Action::Render(GridRender::Engine(tri::develop::Engine::Darktable));
        assert!(h.state().action_unusable(darktable).is_some());
        act(&mut h, darktable);
        assert_eq!(h.state().grid_render, GridRender::Embedded);
        let notice = h.state().notice.clone().map(|n| n.0).unwrap_or_default();
        assert!(notice.contains("Darktable"), "{notice}");
        assert!(
            h.state()
                .action_unusable(Action::Render(GridRender::Cover))
                .is_some(),
            "la couverture sans logiciel"
        );
    }

