    #[test]
    fn the_right_panel_holds_the_grid_settings_in_folding_sections() {
        // Réorganisation du 27/10/2026 : l'ordre, le rendu des vignettes, les piles dans la
        // section « Grille » du panneau de droite ; un clic sur un titre replie la section,
        // retenu d'une session à l'autre.
        let (mut h, _dir) = harness();
        h.state_mut().metadata_panel = true;
        // Les noms d'ordre sont aussi des lignes des Exif (« Nom ») : section repliée.
        h.state_mut().panel_folded.insert("exif".to_string());
        h.set_size(vec2(1400.0, 1200.0));
        h.run_steps(4);
        let current = h.state().order.key;
        let other = tri::sort::SortKey::ALL
            .into_iter()
            .find(|&k| k != current)
            .unwrap();
        // Deux listes déroulantes : l'ordre, puis le rendu des vignettes (#246 ; la barre
        // des filtres n'en a plus).
        // Ouvre la liste n° `n` jusqu'à voir `choice` : le clic d'ouverture se perd
        // parfois sur la CI Windows (08/11/2026, #379).
        let combo = |h: &mut Harness<'_, TriApp>, n: usize, choice: &str| {
            for _ in 0..5 {
                h.get_all_by_role(egui::accesskit::Role::ComboBox)
                    .nth(n)
                    .expect("liste déroulante")
                    .click();
                h.run_steps(2);
                if h.query_by_label(choice).is_some() {
                    return;
                }
            }
            panic!("la liste n° {n} ne s'ouvre pas ({choice})");
        };
        // Les choix d'une liste une fois sa place arrêtée (clic tombé à côté sur la CI
        // Windows, 07/11/2026).
        combo(&mut h, 0, &sort_name(other));
        click_settled(&mut h, &sort_name(other));
        h.run_steps(2);
        assert_eq!(h.state().order.key, other);
        // « RAW », puis « LibRaw » en gris.
        combo(&mut h, 1, "RAW  LibRaw");
        click_settled(&mut h, "RAW  LibRaw");
        h.run_steps(2);
        assert_eq!(
            h.state().grid_render,
            crate::grid_render::GridRender::LibRaw
        );
        // Les piles : une case, et leurs réglages quand elles sont actives.
        assert!(h.query_by_label(&t!("panel-grid-similarity")).is_none());
        // Une fois sa place arrêtée (clic tombé à côté sur la CI, 07/11/2026).
        click_settled(&mut h, &t!("panel-grid-stacks-on"));
        h.run_steps(2);
        assert!(h.state().stacking);
        assert!(h.query_by_label(&t!("panel-grid-similarity")).is_some());
        // Replier « Grille » (la section vient de grandir : clic une fois sa place
        // arrêtée, sinon il tombe à côté, vu sur la CI Ubuntu le 29/10/2026).
        click_settled(&mut h, &t!("panel-section-grid").to_uppercase());
        h.run_steps(2);
        assert!(h.state().panel_folded.contains("grid"));
        assert!(h.query_by_label(&t!("panel-grid-stacks-on")).is_none());
        assert_eq!(
            h.state().display().panel_folded,
            Some(vec!["exif".to_string(), "grid".to_string()])
        );
        // Les réglages d'un filtre n'apparaissent qu'avec lui.
        assert!(h.query_by_label(&t!("panel-clip-over")).is_none());
        click_settled(&mut h, &t!("panel-filter-exposed"));
        h.run_steps(2);
        assert!(h.state().well_exposed);
        assert!(h.query_by_label(&t!("panel-clip-over")).is_some());
    }

    #[test]
    fn thumbnail_info_and_size_from_the_keyboard_and_the_bottom_bar() {
        let (mut h, _dir) = harness();
        // Les curseurs des réglages (#137) repliés : seul compte celui de la grille.
        h.state_mut().panel_folded.insert("adjust".into());
        h.run_steps(3);
        // Fenêtre étroite (1000 points) et panneaux ouverts : les contrôles de la grille
        // passent à la ligne au lieu de recouvrir les notes du bandeau (issue n° 71).
        assert!(h.query_by_label(&Action::ToggleGridInfo.label()).is_some());
        press(&mut h, Key::D, Modifiers::SHIFT);
        press(&mut h, Key::M, Modifiers::SHIFT);
        assert_eq!(
            h.query_all_by_role(egui::accesskit::Role::Slider).count(),
            1
        );
        let default = h.state().gui.grid.cell;
        assert!(h.state().grid_info);
        // Maj+T masque les infos des vignettes, le bouton du bas les remet.
        press(&mut h, Key::T, Modifiers::SHIFT);
        assert!(!h.state().grid_info);
        h.get_by_label(&Action::ToggleGridInfo.label()).click();
        h.run_steps(3);
        assert!(h.state().grid_info);
        // + / - : un palier de plus, de moins (comme le zoom en plein écran).
        h.event(UiEvent::Text("+".into()));
        h.run_steps(3);
        assert_eq!(h.state().grid_cell, default * 1.25);
        h.event(UiEvent::Text("-".into()));
        h.run_steps(3);
        assert_eq!(h.state().grid_cell, default);
        // * (ou le bouton) : 3 images, toutes à l'écran, donc plus grandes.
        h.get_by_label("Toutes les vignettes à l'écran").click();
        h.run_steps(3);
        let fitted = h.state().grid_cell;
        assert!(fitted > default, "{fitted}");
        h.event(UiEvent::Text("-".into()));
        h.run_steps(3);
        h.event(UiEvent::Text("*".into()));
        h.run_steps(3);
        assert_eq!(h.state().grid_cell, fitted);
        // Ctrl + molette ou pince au-dessus de la grille : en continu, bornée (#44).
        h.hover_at(h.ctx.content_rect().center());
        h.event(UiEvent::Zoom(0.8));
        h.run_steps(3);
        assert!((h.state().grid_cell - fitted * 0.8).abs() < 0.01);
        h.event(UiEvent::Zoom(0.001));
        h.run_steps(3);
        assert_eq!(h.state().grid_cell, h.state().gui.grid.cell_min, "plancher");
    }

