    #[test]
    fn stack_keys_apply_to_the_developments_too() {
        // Harmonisation du 31/10/2026 : sans pile de rafale, `s`, `((`, `))`, `(`, `)` et le
        // mode pile visent la pile de développements de la photo.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = dir.path().join("photos");
        for name in ["img0_01.jpg.xmp", "img0_02.jpg.xmp"] {
            std::fs::write(
                photos.join(name),
                r#"<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description rdf:about="" xmlns:xmp="http://ns.adobe.com/xap/1.0/" xmlns:darktable="http://darktable.sf.net/" darktable:xmp_version="5" darktable:history_end="1" xmp:Rating="2"/></rdf:RDF></x:xmpmeta>"#,
            )
            .unwrap();
        }
        // Les développements des seuls logiciels actifs (07/11/2026).
        h.state_mut().developers = fake_darktable();
        h.state_mut().reload_folder(None);
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 5);
        h.state_mut().metadata_panel = false;
        assert_eq!(selected_name(&h), "img0.jpg");
        assert_eq!(h.state().stacks.shown.len(), 3, "pile repliée");
        // `((` ouvre, `))` ferme ; `s` bascule.
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, Action::StackOpen);
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 5, "développements dépliés");
        h.state_mut().perform(&ctx, Action::StackOpen);
        assert!(h.state().hint.is_some(), "plus rien à ouvrir");
        h.state_mut().perform(&ctx, Action::StackClose);
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 3, "repliés");
        type_text(&mut h, "(");
        type_text(&mut h, "(");
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 5);
        type_text(&mut h, ")");
        type_text(&mut h, ")");
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 3);
        // `)` : le dernier développement, `(` : la photo (montrés à la place de la
        // couverture).
        h.state_mut().perform(&ctx, Action::StackLast);
        h.run_steps(2);
        assert_eq!(selected_name(&h), "img0@dt-02.jpg");
        h.state_mut().perform(&ctx, Action::StackFirst);
        h.run_steps(2);
        assert_eq!(selected_name(&h), "img0.jpg");
        // Plein écran, mode pile, en passant en revue les développements : → les
        // parcourt, ← revient.
        h.state_mut().review_developments = true;
        // Pas en JPEG boîtier : la revue y est grisée (05/11/2026).
        h.state_mut().grid_render = crate::grid_render::GridRender::LibRaw;
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        press(&mut h, Key::S, Modifiers::NONE);
        assert!(h.state().stacking, "mode pile");
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(selected_name(&h), "img0@dt-01.jpg");
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(selected_name(&h), "img0@dt-02.jpg");
        press(&mut h, Key::ArrowLeft, Modifiers::NONE);
        assert_eq!(selected_name(&h), "img0@dt-01.jpg");
    }

    #[test]
    fn reviewing_developments_outside_stack_mode_goes_through_each_of_them() {
        // Retour du 05/11/2026 : hors du mode pile, → sautait les développements d'une
        // photo repliée (ou restait bloqué sur l'un d'eux).
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = dir.path().join("photos");
        for name in ["img0_01.jpg.xmp", "img0_02.jpg.xmp"] {
            std::fs::write(
                photos.join(name),
                r#"<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description rdf:about="" xmlns:xmp="http://ns.adobe.com/xap/1.0/" xmlns:darktable="http://darktable.sf.net/" darktable:xmp_version="5" darktable:history_end="1" xmp:Rating="2"/></rdf:RDF></x:xmpmeta>"#,
            )
            .unwrap();
        }
        // Les développements des seuls logiciels actifs (07/11/2026).
        h.state_mut().developers = fake_darktable();
        h.state_mut().reload_folder(None);
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 5);
        h.state_mut().review_developments = true;
        // Pas en JPEG boîtier : la revue y est grisée (05/11/2026).
        h.state_mut().grid_render = crate::grid_render::GridRender::LibRaw;
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert!(!h.state().stacking);
        let mut seen = vec![selected_name(&h)];
        for _ in 0..4 {
            press(&mut h, Key::ArrowRight, Modifiers::NONE);
            h.run_steps(2);
            seen.push(selected_name(&h));
        }
        assert_eq!(
            seen,
            [
                "img0.jpg",
                "img0@dt-01.jpg",
                "img0@dt-02.jpg",
                "img1.jpg",
                "img2.jpg"
            ]
        );
        press(&mut h, Key::ArrowLeft, Modifiers::NONE);
        press(&mut h, Key::ArrowLeft, Modifiers::NONE);
        assert_eq!(selected_name(&h), "img0@dt-02.jpg", "← revient par eux");
        // Sur un développement passé en revue, `r` : avant / après (JPEG boîtier), sans
        // changer le rendu du dossier (06/11/2026).
        let render = h.state().grid_render;
        press(&mut h, Key::R, Modifiers::NONE);
        assert!(h.state().dev_before);
        assert_eq!(h.state().grid_render, render);
        press(&mut h, Key::R, Modifiers::NONE);
        assert!(!h.state().dev_before);
    }

    #[test]
    fn full_screen_stack_browsing_goes_through_developments_to_the_next_photo() {
        // Retour du 04/11/2026 : dans une rafale, la photo 2 avec deux développements ;
        // → arrivait sur ses développements puis restait bloqué sur le dernier.
        let ramp = |tint: u8| {
            image::RgbImage::from_fn(64, 48, |x, _| {
                let v = (x * 255 / 63) as u8;
                image::Rgb([v.saturating_sub(tint), v, v])
            })
        };
        let images = vec![
            ("a1.jpg", ramp(0)),
            ("a2.jpg", ramp(3)),
            ("a3.jpg", ramp(6)),
        ];
        let (mut h, dir) = harness_images(images);
        let photos = dir.path().join("photos");
        for name in ["a2_01.jpg.xmp", "a2_02.jpg.xmp"] {
            std::fs::write(
                photos.join(name),
                r#"<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description rdf:about="" xmlns:darktable="http://darktable.sf.net/" darktable:xmp_version="5" darktable:history_end="1"/></rdf:RDF></x:xmpmeta>"#,
            )
            .unwrap();
        }
        // Les développements des seuls logiciels actifs (07/11/2026).
        h.state_mut().developers = fake_darktable();
        h.state_mut().reload_folder(None);
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 5);
        h.state_mut().stacking = true;
        h.state_mut().settings.similarity.background = true;
        let files = h.state().files.clone();
        let preview = tri::preview::Settings::default();
        let cancel = std::sync::atomic::AtomicBool::new(false);
        for f in &files {
            let sig = tri::preview::compute_signature(f, &preview, &cancel).unwrap();
            h.state_mut().signatures.insert(f.path.clone(), sig);
        }
        h.state_mut().stacks_dirty = true;
        h.run_steps(3);
        assert_eq!(h.state().stacks.count(), 1, "une rafale");
        h.state_mut().metadata_panel = false;
        // En passant en revue les développements.
        h.state_mut().review_developments = true;
        // Pas en JPEG boîtier : la revue y est grisée (05/11/2026).
        h.state_mut().grid_render = crate::grid_render::GridRender::LibRaw;
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        // Au début de la rafale.
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, Action::StackFirst);
        h.run_steps(2);
        let mut seen = vec![selected_name(&h)];
        assert_eq!(seen[0], "a1.jpg");
        for _ in 0..6 {
            press(&mut h, Key::ArrowRight, Modifiers::NONE);
            seen.push(selected_name(&h));
        }
        assert!(seen.contains(&"a2@dt-02.jpg".to_string()), "{seen:?}");
        assert!(
            seen.contains(&"a3.jpg".to_string()),
            "pas bloqué : {seen:?}"
        );
        // Et en revenant : de a3 aux développements de a2, puis a1.
        let mut back = Vec::new();
        for _ in 0..6 {
            press(&mut h, Key::ArrowLeft, Modifiers::NONE);
            back.push(selected_name(&h));
        }
        assert!(back.contains(&"a1.jpg".to_string()), "{back:?}");
        // Par défaut (sans passer en revue) : de photo en photo, a2 sur son
        // développement de couverture, dans la pile comme hors du mode pile (04/11/2026).
        h.state_mut().review_developments = false;
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, Action::StackFirst);
        h.run_steps(2);
        let mut photos_seen = vec![selected_name(&h)];
        for _ in 0..3 {
            press(&mut h, Key::ArrowRight, Modifiers::NONE);
            photos_seen.push(selected_name(&h));
        }
        assert_eq!(photos_seen, ["a1.jpg", "a2.jpg", "a3.jpg", "a3.jpg"]);
        h.state_mut().stacking = false;
        h.state_mut().stacks_dirty = true;
        h.run_steps(2);
        press(&mut h, Key::ArrowLeft, Modifiers::NONE);
        assert_eq!(selected_name(&h), "a2.jpg", "les développements sautés");
        // Le repère ne compte pas les développements quand on ne les passe pas en revue.
        assert!(!h.state().position_text().contains("Dév."));
        h.state_mut().review_developments = true;
        // Pas en JPEG boîtier : la revue y est grisée (05/11/2026).
        h.state_mut().grid_render = crate::grid_render::GridRender::LibRaw;
        assert!(h.state().position_text().contains("Dév. 1 / 3"));
        h.state_mut().review_developments = false;
        press(&mut h, Key::ArrowLeft, Modifiers::NONE);
        assert_eq!(selected_name(&h), "a1.jpg");
    }

    #[test]
    fn the_view_buttons_step_through_the_developments() {
        // #240 : en plein écran, les boutons ‹‹ ›› passent au développement précédent /
        // suivant de la photo, pas à la photo voisine ; absents sans développement.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = dir.path().join("photos");
        for name in ["img0_01.jpg.xmp", "img0_02.jpg.xmp"] {
            std::fs::write(
                photos.join(name),
                r#"<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description rdf:about="" xmlns:xmp="http://ns.adobe.com/xap/1.0/" xmlns:darktable="http://darktable.sf.net/" darktable:xmp_version="5" darktable:history_end="1" xmp:Rating="2"/></rdf:RDF></x:xmpmeta>"#,
            )
            .unwrap();
        }
        // Les développements des seuls logiciels actifs (07/11/2026).
        h.state_mut().developers = fake_darktable();
        h.state_mut().reload_folder(None);
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 5);
        h.state_mut().metadata_panel = false;
        // La pile de développements est repliée : → saute les clones cachés.
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(selected_name(&h), "img1.jpg");
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        h.run_steps(2);
        assert!(
            h.query_by_label(&Action::DevNext.label()).is_none(),
            "sans développement : pas de bouton"
        );
        press(&mut h, Key::ArrowLeft, Modifiers::NONE);
        assert_eq!(selected_name(&h), "img0.jpg");
        h.run_steps(2);
        h.get_by_label(&Action::DevNext.label()).click();
        h.run_steps(3);
        assert_eq!(selected_name(&h), "img0@dt-01.jpg", "suivant : le clone 1");
        h.get_by_label(&Action::DevNext.label()).click();
        h.run_steps(3);
        assert_eq!(selected_name(&h), "img0@dt-02.jpg", "puis le clone 2");
        h.get_by_label(&Action::DevPrev.label()).click();
        h.run_steps(3);
        assert_eq!(
            selected_name(&h),
            "img0@dt-01.jpg",
            "précédent : le clone 1"
        );
    }

