    #[test]
    fn the_grid_cursor_hides_for_an_overview() {
        let (mut h, dir) = harness();
        h.run_steps(5);
        let image = dir.path().join("photos/img0.jpg");
        // Échap sans rien à fermer : plus d'image en surbrillance.
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(h.state().cursor_hidden);
        // Une note ne vise pas une image qu'on ne voit pas : le curseur revient seulement.
        press(&mut h, Key::Num3, Modifiers::NONE);
        assert!(!h.state().cursor_hidden);
        assert_eq!(h.state().folder.notes.notes(&image).stars, 0, "rien noté");
        // Une flèche : le curseur revient là où il était, sans bouger.
        press(&mut h, Key::Escape, Modifiers::NONE);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert!(!h.state().cursor_hidden);
        assert_eq!(h.state().selected, 0);
        // Les filtres, les panneaux… restent utilisables curseur masqué.
        press(&mut h, Key::Escape, Modifiers::NONE);
        press(&mut h, Key::N, Modifiers::SHIFT);
        assert!(
            h.state().cursor_hidden,
            "<leader> Maj+J : bandeau, curseur toujours masqué"
        );
        // Clic dans le vide, sous les vignettes : masqué ; clic sur une image : revenu.
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        let rects = h.state().cell_rects.clone();
        let rect = rects[0].1;
        let click = |h: &mut Harness<'_, TriApp>, pos: egui::Pos2| {
            h.event(UiEvent::PointerMoved(pos));
            for pressed in [true, false] {
                h.event(UiEvent::PointerButton {
                    pos,
                    button: egui::PointerButton::Primary,
                    pressed,
                    modifiers: Modifiers::NONE,
                });
            }
            h.run_steps(3);
        };
        // Place vide : la colonne de la deuxième image, la ligne de la troisième.
        let last = rects.iter().map(|(_, r)| *r).fold(rect, |a, r| a.union(r));
        let empty = egui::pos2(
            last.max.x - rect.width() / 2.0,
            last.max.y - rect.height() / 2.0,
        );
        assert!(rects.iter().all(|(_, r)| !r.contains(empty)));
        click(&mut h, empty);
        assert!(h.state().cursor_hidden, "clic dans le vide");
        click(&mut h, rect.center());
        assert!(!h.state().cursor_hidden, "clic sur une image");
    }

    #[test]
    fn shift_click_adds_a_range_and_command_click_toggles() {
        let names = ["a.jpg", "b.jpg", "c.jpg", "d.jpg"];
        let (mut h, _dir) = harness_files(&names, 64, 48);
        h.run_steps(5);
        let center = |h: &Harness<'_, TriApp>, i: usize| {
            h.state()
                .cell_rects
                .iter()
                .find(|(j, _)| *j == i)
                .unwrap()
                .1
                .center()
        };
        let click = |h: &mut Harness<'_, TriApp>, i: usize, modifiers: Modifiers| {
            let pos = center(h, i);
            h.event(UiEvent::ModifiersChanged(modifiers));
            h.event(UiEvent::PointerMoved(pos));
            for pressed in [true, false] {
                h.event(UiEvent::PointerButton {
                    pos,
                    button: egui::PointerButton::Primary,
                    pressed,
                    modifiers,
                });
            }
            h.run_steps(3);
            h.event(UiEvent::ModifiersChanged(Modifiers::NONE));
        };
        click(&mut h, 2, Modifiers::SHIFT);
        assert_eq!(h.state().selection.len(), 3, "a à c");
        assert_eq!(selected_name(&h), "c.jpg");
        click(&mut h, 1, Modifiers::COMMAND);
        assert_eq!(h.state().selection.len(), 2, "b retirée");
        click(&mut h, 3, Modifiers::NONE);
        assert!(
            h.state().selection.is_empty(),
            "clic simple : sélection effacée"
        );
        // Retour du 07/11/2026 : l'image courante (en surbrillance, d) compte ; le premier
        // Cmd+clic sur une autre les prend toutes les deux, et = les compare aussitôt.
        click(&mut h, 2, Modifiers::COMMAND);
        assert_eq!(h.state().selection.len(), 2, "c et d");
        type_text(&mut h, "=");
        assert_eq!(h.state().mode, Mode::Compare);
        assert_eq!(h.state().compare.len(), 2);
    }

    #[test]
    fn the_loupe_works_in_comparison_on_the_image_under_the_pointer() {
        let names = ["a.jpg", "b.jpg", "c.jpg"];
        let (mut h, _dir) = harness_files(&names, 64, 48);
        h.run_steps(3);
        press(&mut h, Key::Space, Modifiers::SHIFT);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        press(&mut h, Key::Space, Modifiers::SHIFT);
        type_text(&mut h, "=");
        assert_eq!(h.state().mode, Mode::Compare);
        h.state_mut().gui.zoom.loupe_delay_ms = 0;
        h.event(UiEvent::Key {
            key: Key::M,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: Modifiers::NONE,
        });
        // `t` maintenue, le pointeur passe sur chaque image : la loupe suit. Balayé tant
        // qu'il faut : une image pas encore affichée n'a pas de loupe (CI Windows lente,
        // 08/11/2026 ; seule l'image survolée enregistre sa place, `loupe_rects`).
        let area = h.ctx.content_rect();
        let mut seen = HashSet::new();
        let deadline = Instant::now() + Duration::from_secs(60);
        while seen.len() < 2 {
            assert!(
                Instant::now() < deadline,
                "loupe sur plusieurs images : {seen:?}"
            );
            for k in 1..20 {
                for y in [0.35, 0.5, 0.65] {
                    let at = pos2(
                        area.left() + area.width() * k as f32 / 20.0,
                        area.top() + area.height() * y,
                    );
                    h.hover_at(at);
                    h.run_steps(2);
                    if h.state().loupe_on {
                        seen.insert(h.state().loupe_index);
                    }
                }
            }
        }
        assert_eq!(selected_name(&h), "c.jpg", "l'image active ne change pas");
    }

    #[test]
    fn the_held_loupe_moves_with_the_navigation_keys() {
        // Idée de l'utilisateur, 06/11/2026 : m + flèches (hjkl en vim) déplace la loupe,
        // avec Maj d'un grand pas, sans changer d'image.
        let (mut h, _dir) = harness_with(640, 480);
        h.run_steps(3);
        press(&mut h, Key::Enter, Modifiers::NONE);
        // L'image affichée d'abord (sa place) : sans elle, pas de loupe (CI Linux lente,
        // 07/11/2026).
        run_until(&mut h, |app| app.loupe_rects.contains_key(&app.selected));
        h.state_mut().gui.zoom.loupe_delay_ms = 0;
        h.event(UiEvent::Key {
            key: Key::M,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: Modifiers::NONE,
        });
        h.run_steps(3);
        let selected = h.state().selected;
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(h.state().selected, selected, "pas d'image suivante");
        // Premier appui : la loupe se pose au centre (pointeur ailleurs) ; ensuite un pas,
        // puis un grand pas avec Maj, mesurés dans la loupe.
        let (_, anchor) = h.state().loupe_point.expect("placée au clavier");
        assert_eq!(anchor, vec2(0.5, 0.5));
        h.run_steps(2);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        let (_, first) = h.state().loupe_point.unwrap();
        assert!(first.x > 0.5 && (first.y - 0.5).abs() < 1e-3, "{first:?}");
        press(&mut h, Key::ArrowRight, Modifiers::SHIFT);
        let (_, second) = h.state().loupe_point.unwrap();
        assert!(
            second.x - first.x > (first.x - 0.5) * 3.0 || second.x >= 1.0,
            "grand pas : {second:?}"
        );
        assert!(h.state().loupe_on, "la loupe est là, au point visé");
        // Touche relâchée : les flèches changent d'image de nouveau.
        h.event(UiEvent::Key {
            key: Key::M,
            physical_key: None,
            pressed: false,
            repeat: false,
            modifiers: Modifiers::NONE,
        });
        h.run_steps(2);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_ne!(h.state().selected, selected);
        assert!(h.state().loupe_point.is_none());
    }

    #[test]
    fn the_loupe_works_in_the_grid_too() {
        // Demandé le 06/11/2026 : la loupe n'existait qu'en plein écran et en comparaison.
        let (mut h, _dir) = harness_with(640, 480);
        h.run_steps(5);
        assert_eq!(h.state().mode, Mode::Grid);
        h.state_mut().gui.zoom.loupe_delay_ms = 0;
        h.event(UiEvent::Key {
            key: Key::M,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: Modifiers::NONE,
        });
        // Sur la deuxième vignette : la loupe y est, son 1:1 demandé. Les vignettes
        // d'abord (lentes à venir sur les machines de la CI).
        run_until(&mut h, |app| app.grid_images.len() >= 2);
        let (index, rect) = h.state().grid_images[1];
        h.hover_at(rect.center());
        h.run_steps(3);
        assert!(h.state().loupe_on);
        assert_eq!(h.state().loupe_index, index);
        assert_eq!(h.state().displayed(), [index]);
        // Au clavier, sur la sélectionnée, sans bouger le curseur de la grille.
        let selected = h.state().selected;
        h.hover_at(pos2(1.0, 1.0));
        h.run_steps(2);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(h.state().selected, selected);
        assert_eq!(h.state().loupe_point.map(|(i, _)| i), Some(selected));
        h.run_steps(2);
        assert!(h.state().loupe_on);
        assert_eq!(h.state().loupe_index, selected);
        // Le pas se mesure dans la loupe (retour du 06/11/2026 : sur une vignette, il
        // sautait des centaines de pixels).
        // La taille de l'image dans la loupe au moment de l'appui : le 1:1 peut finir de
        // charger juste après et la changer (vu sur la CI Windows le 07/11/2026). Son 1:1
        // d'abord (sur la CI Ubuntu, la mesure tombait encore pendant ce chargement).
        run_until(&mut h, |app| {
            let file = &app.files[selected];
            let level = view::zoom_level(
                file.kind,
                app.source_for(file),
                app.developed_level(&file.path),
            );
            app.loaded(selected, level)
        });
        h.run_steps(3);
        let before = h.state().loupe_point.unwrap().1;
        let whole = h.state().loupe_sizes[&selected];
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        let after = h.state().loupe_point.unwrap().1;
        let moved = (after.x - before.x) * whole.x;
        let step = h.state().gui.zoom.loupe_step;
        assert!(
            (moved - step).abs() < 1.0 || after.x >= 1.0,
            "{moved} points pour un pas de {step}"
        );
    }

    #[test]
    fn no_loupe_over_the_bottom_bar() {
        // Retour du 07/11/2026 : une vignette coupée par la barre du bas continuait
        // dessous ; la loupe restait quand on cliquait − et + pour la régler.
        let names: Vec<String> = (0..40).map(|i| format!("img{i:02}.jpg")).collect();
        let names: Vec<&str> = names.iter().map(String::as_str).collect();
        let (mut h, _dir) = harness_files(&names, 640, 480);
        h.state_mut().gui.zoom.loupe_delay_ms = 0;
        // Toutes les vignettes calculées d'abord (lentes sur les machines de la CI : une
        // vignette sans texture n'a pas de place dans `grid_images`).
        run_until(&mut h, |app| {
            app.status.iter().all(|s| s.thumbnail == Avail::Ready)
        });
        // Une hauteur de fenêtre où une vignette passe sous le + de la barre ; quelques
        // images pour que les textures des vignettes devenues visibles arrivent.
        let mut found = None;
        'heights: for height in (300..800).step_by(7) {
            h.set_size(vec2(1800.0, height as f32));
            for _ in 0..10 {
                h.run_steps(1);
                let plus = h.get_by_label("+").rect().center();
                if h.state().grid_images.iter().any(|(_, r)| r.contains(plus)) {
                    found = Some(plus);
                    break 'heights;
                }
                std::thread::sleep(Duration::from_millis(5));
            }
        }
        let plus = found.expect("une vignette sous la barre");
        h.event(UiEvent::Key {
            key: Key::M,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: Modifiers::NONE,
        });
        h.hover_at(plus - vec2(1.0, 0.0));
        h.run_steps(1);
        h.hover_at(plus);
        h.run_steps(3);
        assert!(!h.state().loupe_on, "pas de loupe sous la barre");
    }

    #[test]
    fn the_zoom_is_typed_or_stepped_like_the_loupe() {
        // Décidé le 07/11/2026 : tout ce qui vaut pour la loupe (m) vaut pour le zoom (z).
        let (mut h, _dir) = harness_with(640, 480);
        h.run_steps(3);
        press(&mut h, Key::Enter, Modifiers::NONE);
        h.run_steps(3);
        assert!(h.state().zoom.is_none(), "ajusté");
        // `<leader> z 2`, puis la pause : 200 %.
        leader(&mut h, &[(Key::Z, Modifiers::NONE)]);
        press(&mut h, Key::Num2, Modifiers::NONE);
        if let Some((_, last)) = &mut h.state_mut().loupe_entry {
            *last -= Duration::from_secs(5);
        }
        h.run_steps(2);
        assert!(h.state().zoom.is_some());
        assert_eq!(h.state().zoom_scale, 2.0);
        assert_eq!(h.state().loupe_scale, 1.0, "la loupe ne bouge pas");
        // Ctrl+J sans la loupe tenue : le zoom d'un palier.
        press(&mut h, Key::J, Modifiers::CTRL);
        assert_eq!(h.state().zoom_scale, 1.0);
        assert_eq!(h.state().loupe_scale, 1.0);
        // Idée de l'utilisateur, 07/11/2026 : `<leader> z /` ajusté, `<leader> z z` 100 %,
        // `<leader> m m` la loupe à 100 %.
        leader(&mut h, &[(Key::Z, Modifiers::NONE)]);
        type_text(&mut h, "/");
        assert!(h.state().zoom.is_none(), "ajusté");
        assert!(h.state().loupe_entry.is_none());
        leader(
            &mut h,
            &[(Key::Z, Modifiers::NONE), (Key::Z, Modifiers::NONE)],
        );
        assert!(h.state().loupe_entry.is_none());
        assert!(h.state().zoom.is_some());
        assert_eq!(h.state().zoom_scale, 1.0);
        h.state_mut().set_loupe_scale(2.0);
        leader(
            &mut h,
            &[(Key::M, Modifiers::NONE), (Key::M, Modifiers::NONE)],
        );
        assert!(h.state().loupe_entry.is_none());
        assert_eq!(h.state().loupe_scale, 1.0);
        // Après un chiffre, la touche ne remet plus à 100 % : elle applique ce qui est
        // tapé.
        leader(
            &mut h,
            &[(Key::M, Modifiers::NONE), (Key::Num3, Modifiers::NONE)],
        );
        press(&mut h, Key::M, Modifiers::NONE);
        assert_eq!(h.state().loupe_scale, 3.0);
        // Ouverte depuis la palette : pas de touche qui remet à 100 %.
        act(&mut h, Action::LoupeScaleEntry);
        press(&mut h, Key::M, Modifiers::NONE);
        assert_eq!(h.state().loupe_scale, 3.0);
    }

    #[test]
    fn the_magnification_entries_have_their_own_menu() {
        // Retour du 07/11/2026 : dans le menu des suites, `m` et `z` ont un niveau de plus
        // (les chiffres, la touche retapée pour 100 %, `/` pour l'ajusté).
        let (mut h, _dir) = harness();
        h.run_steps(3);
        h.state_mut().gui.key_menu_delay_ms = 0;
        act(&mut h, Action::Open);
        leader(&mut h, &[]);
        h.run_steps(3);
        let loupe = t!("key-menu-more", group = t!("key-menu-loupe"));
        let zoom = t!("key-menu-more", group = t!("key-menu-zoom"));
        assert!(h.query_by_label(&loupe).is_some());
        assert!(h.query_by_label(&zoom).is_some());
        // La loupe : les chiffres et `m` (100 %).
        press(&mut h, Key::M, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().loupe_entry.is_some());
        assert!(h.query_by_label(&t!("entry-menu-digits")).is_some());
        assert!(h.query_by_label("100 %").is_some());
        // Un chiffre tapé : le menu s'efface.
        press(&mut h, Key::Num2, Modifiers::NONE);
        assert!(h.query_by_label(&t!("entry-menu-digits")).is_none());
        press(&mut h, Key::Escape, Modifiers::NONE);
        // Le zoom : aussi l'ajusté.
        leader(&mut h, &[(Key::Z, Modifiers::NONE)]);
        h.run_steps(2);
        assert!(h.query_by_label(&t!("entry-menu-digits")).is_some());
        // « Ajusté » : la valeur de la barre du bas, et la ligne du menu.
        assert_eq!(h.query_all_by_label(&t!("zoom-fit-value")).count(), 2);
    }

    #[test]
    fn the_loupe_magnification_is_typed_or_stepped() {
        // Idée de l'utilisateur, 06/11/2026 : `<leader> m` puis 3 chiffres (aussitôt), 2
        // (dizaines) ou 1 (centaines) après une pause ; Ctrl+K / Ctrl+J par paliers.
        assert_eq!(loupe_entry_percent("150"), Some(150));
        assert_eq!(loupe_entry_percent("20"), Some(200));
        assert_eq!(loupe_entry_percent("01"), Some(10));
        assert_eq!(loupe_entry_percent("2"), Some(200));
        assert_eq!(loupe_entry_percent(""), None);
        let (mut h, _dir) = harness();
        h.run_steps(3);
        assert_eq!(h.state().loupe_scale, 1.0);
        // Trois chiffres : aussitôt, sans noter la photo.
        leader(&mut h, &[(Key::M, Modifiers::NONE)]);
        assert!(h.state().loupe_entry.is_some());
        for key in [Key::Num1, Key::Num5, Key::Num0] {
            press(&mut h, key, Modifiers::NONE);
        }
        assert_eq!(h.state().loupe_scale, 1.5);
        assert!(h.state().loupe_entry.is_none());
        let file = h.state().files[0].path.clone();
        assert_eq!(h.state().folder.notes.notes(&file).stars, 0, "pas noté");
        // Un chiffre, puis la pause : en centaines.
        leader(&mut h, &[(Key::M, Modifiers::NONE)]);
        press(&mut h, Key::Num2, Modifiers::NONE);
        if let Some((_, last)) = &mut h.state_mut().loupe_entry {
            *last -= Duration::from_secs(5);
        }
        h.run_steps(2);
        assert_eq!(h.state().loupe_scale, 2.0);
        // Un chiffre tapé lentement après la pause (Maj sur AZERTY, 07/11/2026) complète
        // encore le nombre, sans noter la photo. Sous Linux, Maj arrive aussi comme une
        // touche, avant le chiffre : elle ne ferme pas la saisie.
        for key in [Key::ShiftLeft, Key::ShiftRight, Key::ControlLeft] {
            h.event(UiEvent::Key {
                key,
                physical_key: Some(key),
                pressed: true,
                repeat: false,
                modifiers: Modifiers::NONE,
            });
        }
        h.run_steps(2);
        press(&mut h, Key::Num5, Modifiers::SHIFT);
        assert_eq!(
            h.state().loupe_entry.as_ref().map(|e| e.0.as_str()),
            Some("25")
        );
        press(&mut h, Key::Num0, Modifiers::SHIFT);
        assert_eq!(h.state().loupe_scale, 2.5);
        assert_eq!(
            h.state().folder.notes.notes(&file).stars,
            0,
            "toujours pas noté"
        );
        // Bien plus tard, un chiffre redevient une note.
        leader(&mut h, &[(Key::M, Modifiers::NONE)]);
        press(&mut h, Key::Num2, Modifiers::NONE);
        if let Some((_, last)) = &mut h.state_mut().loupe_entry {
            *last -= Duration::from_secs(5);
        }
        h.run_steps(2);
        if let Some((_, closed)) = &mut h.state_mut().loupe_entry_done {
            *closed -= Duration::from_secs(5);
        }
        press(&mut h, Key::Num3, Modifiers::NONE);
        assert_eq!(h.state().loupe_scale, 2.0);
        assert_eq!(h.state().folder.notes.notes(&file).stars, 3, "noté");
        // Linux (trace de l'utilisateur, 07/11/2026) : Maj arrive comme une touche juste
        // après `<leader> m`, puis les chiffres avec Maj.
        leader(&mut h, &[(Key::M, Modifiers::NONE)]);
        h.event(UiEvent::Key {
            key: Key::ShiftRight,
            physical_key: Some(Key::ShiftRight),
            pressed: true,
            repeat: false,
            modifiers: Modifiers::NONE,
        });
        h.run_steps(2);
        for key in [Key::Num1, Key::Num2, Key::Num5] {
            press(&mut h, key, Modifiers::SHIFT);
        }
        assert_eq!(h.state().loupe_scale, 1.25);
        assert_eq!(
            h.state().folder.notes.notes(&file).stars,
            3,
            "note inchangée"
        );
        h.state_mut().set_loupe_scale(2.0);
        // Échap annule ; 0 est ignoré.
        leader(&mut h, &[(Key::M, Modifiers::NONE)]);
        press(&mut h, Key::Num4, Modifiers::NONE);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().loupe_scale, 2.0);
        leader(&mut h, &[(Key::M, Modifiers::NONE)]);
        for _ in 0..3 {
            press(&mut h, Key::Num0, Modifiers::NONE);
        }
        assert_eq!(h.state().loupe_scale, 2.0);
        // Paliers, la loupe tenue : Ctrl+K au suivant (400 %), Ctrl+J au précédent (sans
        // elle, c'est le zoom, 07/11/2026).
        h.event(UiEvent::Key {
            key: Key::M,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: Modifiers::NONE,
        });
        h.run_steps(2);
        press(&mut h, Key::K, Modifiers::CTRL);
        assert_eq!(h.state().loupe_scale, 4.0);
        press(&mut h, Key::J, Modifiers::CTRL);
        press(&mut h, Key::J, Modifiers::CTRL);
        assert_eq!(h.state().loupe_scale, 1.0);
        // La roulette, la loupe tenue : un palier par cran, la grille ne défile pas.
        let offset = h.state().scroll_offset;
        h.event(UiEvent::MouseWheel {
            unit: egui::MouseWheelUnit::Line,
            delta: vec2(0.0, 1.0),
            modifiers: Modifiers::NONE,
            phase: egui::TouchPhase::Move,
            source: egui::MouseWheelSource::Wheel,
        });
        h.run_steps(3);
        assert_eq!(h.state().loupe_scale, 2.0);
        assert_eq!(h.state().scroll_offset, offset);
    }

    #[test]
    fn with_nothing_highlighted_the_compare_key_compares_everything() {
        // Retour du 07/11/2026 : curseur masqué, rien de sélectionné, le premier = ne
        // faisait que remontrer le curseur (le bouton marchait du premier coup).
        let (mut h, _dir) = harness();
        h.run_steps(3);
        h.state_mut().cursor_hidden = true;
        let before = h.state().selected;
        type_text(&mut h, "=");
        assert_eq!(h.state().mode, Mode::Compare);
        assert_eq!(h.state().compare.len(), 3);
        // Sortie : la grille à l'identique, rien en surbrillance (retour du 07/11/2026) ;
        // et la comparaison suivante prend de nouveau tout.
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Grid);
        assert!(h.state().cursor_hidden, "toujours rien en surbrillance");
        assert_eq!(h.state().selected, before);
        type_text(&mut h, "=");
        assert_eq!(h.state().compare.len(), 3, "de nouveau tout");
    }

