    #[test]
    fn dialogs_can_be_moved_by_dragging_their_background() {
        let (mut h, _dir) = harness();
        h.run_steps(3);
        press(&mut h, Key::F2, Modifiers::NONE);
        let title = "Renommer « img0.jpg »";
        let before = h.get_by_label(title).rect().center();
        let after = before + vec2(-120.0, 90.0);
        h.event(UiEvent::PointerMoved(before));
        h.event(UiEvent::PointerButton {
            pos: before,
            button: egui::PointerButton::Primary,
            pressed: true,
            modifiers: Modifiers::NONE,
        });
        h.run_steps(1);
        for step in 1..=6 {
            h.event(UiEvent::PointerMoved(
                before + (after - before) * step as f32 / 6.0,
            ));
            h.run_steps(1);
        }
        h.event(UiEvent::PointerButton {
            pos: after,
            button: egui::PointerButton::Primary,
            pressed: false,
            modifiers: Modifiers::NONE,
        });
        h.run_steps(3);
        let moved = h.get_by_label(title).rect().center();
        assert!((moved - after).length() < 2.0, "{before:?} → {moved:?}");
        assert!(h.state().file_dialog.is_some(), "toujours ouverte");
        // Par le fond (la marge au-dessus du titre), non (retour du 01/11/2026 : glisser
        // une pastille à côté déplaçait la fenêtre de réglages).
        let edge = egui::pos2(moved.x, h.get_by_label(title).rect().top() - 5.0);
        h.event(UiEvent::PointerMoved(edge));
        h.event(UiEvent::PointerButton {
            pos: edge,
            button: egui::PointerButton::Primary,
            pressed: true,
            modifiers: Modifiers::NONE,
        });
        h.run_steps(1);
        for step in 1..=4 {
            h.event(UiEvent::PointerMoved(edge + vec2(0.0, 20.0 * step as f32)));
            h.run_steps(1);
        }
        h.event(UiEvent::PointerButton {
            pos: edge + vec2(0.0, 80.0),
            button: egui::PointerButton::Primary,
            pressed: false,
            modifiers: Modifiers::NONE,
        });
        h.run_steps(3);
        let still = h.get_by_label(title).rect().center();
        assert!((still - moved).length() < 2.0, "{moved:?} → {still:?}");
    }

    #[test]
    fn the_display_state_survives_a_restart() {
        let dir = tempfile::tempdir().unwrap();
        let mut settings = AppSettings::default();
        settings.cache.dir = Some(dir.path().join("cache"));
        settings.data.dir = Some(dir.path().join("data"));
        settings.places.watch_ms = 0;
        let mut first = TriApp::new(None, settings.clone(), None);
        assert!(
            first.focus_point,
            "valeur de la configuration au premier lancement"
        );
        first.focus_point = false;
        first.histogram = !first.histogram;
        first.save_display();
        let histogram = first.histogram;
        let second = TriApp::new(None, settings.clone(), None);
        assert!(!second.focus_point, "collimateur masqué gardé");
        assert_eq!(second.histogram, histogram);
        // Désactivé : toujours la configuration.
        settings.gui.remember_display = false;
        let third = TriApp::new(None, settings, None);
        assert!(third.focus_point);
    }

    #[test]
    fn one_scale_control_sets_the_zoom_or_the_loupe() {
        // 07/11/2026 : − et + de la loupe partaient dans la notation ; puis un seul réglage
        // pour le zoom et la loupe (la touche de loupe tenue), la valeur tapée, l'icône
        // qui réinitialise. Fenêtre large : en grille, il ne s'affiche que s'il reste la
        // place. Des images plus grandes que la vue, pour que + zoome.
        let (mut h, _dir) = harness_with(2400, 1600);
        h.set_size(vec2(1800.0, 700.0));
        h.run_steps(3);
        // En grille : la loupe.
        assert_eq!(h.state().loupe_scale, 1.0);
        click_settled(&mut h, "+");
        h.run_steps(2);
        assert!(h.state().loupe_scale > 1.0, "{}", h.state().loupe_scale);
        click_settled(&mut h, "−");
        click_settled(&mut h, "−");
        h.run_steps(2);
        assert!(h.state().loupe_scale < 1.0, "{}", h.state().loupe_scale);
        click_settled(&mut h, &t!("loupe-reset"));
        h.run_steps(2);
        assert_eq!(h.state().loupe_scale, 1.0);
        let file = h.state().files[h.state().selected].path.clone();
        assert_eq!(h.state().folder.notes.notes(&file).stars, 0, "pas noté");
        // En plein écran : le zoom. L'image en grand d'abord (CI lente, 07/11/2026 : sur la
        // vignette, l'ajusté dépassait le zoom maximal, et + ne faisait rien).
        act(&mut h, Action::Open);
        run_until(&mut h, |app| app.fit_scale < 1.0);
        click_settled(&mut h, "+");
        h.run_steps(2);
        assert!(h.state().zoom.is_some(), "zoomé");
        assert_eq!(h.state().loupe_scale, 1.0, "la loupe ne bouge pas");
        click_settled(&mut h, &t!("zoom-reset"));
        h.run_steps(2);
        assert!(h.state().zoom.is_none(), "ajusté");
        // La valeur cliquée se tape : Entrée applique.
        click_settled(&mut h, &t!("zoom-fit-value"));
        h.run_steps(3);
        assert!(h.state().scale_edit.is_some());
        type_text(&mut h, "150");
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert!(h.state().scale_edit.is_none());
        assert_eq!(h.state().zoom_scale, 1.5);
        assert!(h.state().zoom.is_some());
        // Échap annule, sans revenir à la grille.
        click_settled(&mut h, "150 %");
        h.run_steps(3);
        type_text(&mut h, "40");
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(h.state().scale_edit.is_none());
        assert_eq!(h.state().zoom_scale, 1.5);
        assert_eq!(h.state().mode, Mode::View);
        click_settled(&mut h, &t!("zoom-reset"));
        h.run_steps(2);
        // La touche de loupe tenue : la loupe, et le pointeur reste visible.
        h.state_mut().mouse_active = true;
        for repeat in [false, true] {
            h.event(UiEvent::Key {
                key: Key::M,
                physical_key: None,
                pressed: true,
                repeat,
                modifiers: Modifiers::NONE,
            });
            h.run_steps(2);
        }
        assert!(h.state().mouse_active, "pointeur gardé");
        click_settled(&mut h, "+");
        h.run_steps(2);
        assert!(h.state().loupe_scale > 1.0, "{}", h.state().loupe_scale);
        assert!(h.state().zoom.is_none(), "le zoom ne bouge pas");
        click_settled(&mut h, &t!("loupe-reset"));
        h.run_steps(2);
        assert_eq!(h.state().loupe_scale, 1.0);
    }

