    #[test]
    fn the_grid_s_own_renders_stop_when_another_folder_opens() {
        // #303 : les rendus lancés d'office pour la grille continuaient après avoir changé
        // de dossier ; un lot demandé à la main va au bout.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = dir.path().join("photos");
        let other = dir.path().join("other");
        std::fs::create_dir(&other).unwrap();
        let batch = |app: &TriApp| {
            let engine = app.engine.as_ref().unwrap();
            crate::develop_batch::DevelopBatch::start(
                photos.clone(),
                Vec::new(),
                CachedPreviews {
                    cache: engine.cache.clone(),
                    settings: engine.preview,
                    developers: tri::develop::Developers::none().into(),
                },
                None,
                || {},
            )
        };
        let open = |h: &mut Harness<'_, TriApp>, to: &Path| {
            h.state_mut().open_folder(to);
            let to = to.to_path_buf();
            run_until(h, move |app| app.folder.dir == to && app.opening.is_none());
        };
        let start = |h: &mut Harness<'_, TriApp>, auto: bool| {
            let b = batch(h.state());
            let flag = b.cancel_flag();
            h.state_mut().develop_batch = Some(b);
            h.state_mut().develop_batch_auto = auto;
            flag
        };
        let cancelled = |f: &Arc<AtomicBool>| f.load(std::sync::atomic::Ordering::Relaxed);
        // À la main : il va au bout.
        let manual = start(&mut h, false);
        open(&mut h, &other);
        assert!(!cancelled(&manual));
        // D'office pour la grille de `photos` : rouvrir `photos` ne l'arrête pas…
        open(&mut h, &photos);
        let auto = start(&mut h, true);
        open(&mut h, &photos);
        assert!(!cancelled(&auto));
        // … un autre dossier, si.
        let auto = start(&mut h, true);
        open(&mut h, &other);
        assert!(cancelled(&auto), "interrompu");
    }

    #[test]
    fn the_developed_filter_is_greyed_without_developments() {
        // #305 : un dossier sans aucun développement, la case « Développées » ne servait à
        // rien.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        h.state_mut().developers = fake_darktable();
        h.state_mut().refresh_any_developed();
        let developed = |app: &TriApp| {
            app.content_toggles()
                .into_iter()
                .find(|t| t.0 == Action::FilterDeveloped)
                .map(|t| t.2)
        };
        assert_eq!(
            developed(h.state()),
            Some(false),
            "rien de développé : grisée"
        );
        // Allumée quand même (réglage retenu) : utilisable, pour l'éteindre.
        h.state_mut().developed_on = true;
        assert_eq!(developed(h.state()), Some(true));
        h.state_mut().developed_on = false;
        // Une image de développement dans le dossier : utilisable.
        h.state_mut().any_developed = true;
        assert_eq!(developed(h.state()), Some(true));
        // Deux logiciels, un seul avec des développements : l'autre est grisé dans la
        // liste (retour du 05/11/2026).
        h.state_mut().developers =
            fake_darktable().with(Arc::new(FakeDeveloper(tri::develop::Engine::RapidRaw)));
        h.state_mut().developed_in = vec![tri::develop::Engine::Darktable];
        h.state_mut().developed_on = true;
        h.state_mut().metadata_panel = true;
        h.run_steps(3);
        let enabled = |h: &Harness<'_, TriApp>, name: &str| {
            !format!("{:?}", h.get_by_label(name)).contains("disabled: true")
        };
        assert!(enabled(&h, "Darktable"));
        assert!(!enabled(&h, "RapidRAW"), "rien de RapidRAW : grisé");
    }

    #[test]
    fn full_screen_says_when_the_list_or_the_stack_ends() {
        // #307 : au bout de la pile ou du dossier, le défilement s'arrêtait sans rien dire.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        let notice = |h: &Harness<'_, TriApp>| h.state().end_notice.clone().map(|n| n.0);
        press(&mut h, Key::ArrowLeft, Modifiers::NONE);
        assert_eq!(notice(&h), Some(t!("end-list-first")));
        h.run_steps(2);
        assert!(
            h.query_by_label(&t!("end-list-first")).is_some(),
            "montré sur l'image"
        );
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        h.state_mut().end_notice = None;
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(notice(&h), Some(t!("end-list-last")));
        // Mode pile, sur la dernière pile : la fin de la sélection, pas seulement de la
        // pile (on voit tout de suite qu'il n'y a plus rien après).
        h.state_mut().end_notice = None;
        press(&mut h, Key::S, Modifiers::NONE);
        assert!(h.state().stacking);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(notice(&h), Some(t!("end-list-last")));
        // Une pile qui a des voisines : le bout de la pile.
        h.state_mut().end_notice = None;
        press(&mut h, Key::ArrowUp, Modifiers::NONE);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(notice(&h), Some(t!("end-stack-last")));
        // Passer à la pile suivante l'efface (retour du 05/11/2026).
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().end_notice.is_none(), "effacé sur une autre image");
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        // 0 : jamais.
        h.state_mut().gui.end.seconds = 0.0;
        h.run_steps(2);
        assert!(h.state().end_notice.is_none());
    }

