    #[test]
    fn the_sidecars_dialog_creates_the_missing_ones_for_the_chosen_software() {
        // Boîte « Générer les sidecars » (31/10/2026) : RapidRAW choisi, la photo notée
        // reçoit son `.rrdata`, celle sans note non ; le compte est annoncé avant. La
        // liste ne propose que les logiciels installés (ici RapidRAW et RawTherapee, pas
        // ART), comme celle des rendus.
        let (mut h, dir) = harness();
        let photos = dir.path().join("photos");
        h.state_mut().developers = tri::develop::Developers::none()
            .with(Arc::new(FakeDeveloper(tri::develop::Engine::RapidRaw)))
            .with(Arc::new(FakeDeveloper(tri::develop::Engine::RawTherapee)));
        press(&mut h, Key::Num3, Modifiers::NONE);
        // Une seule liste déroulante : celle de la boîte.
        h.state_mut().metadata_panel = false;
        h.state_mut().filter_bar = false;
        let images: Vec<PathBuf> = h.state().files.iter().map(|f| f.path.clone()).collect();
        h.state_mut()
            .open_sidecars_dialog(images, "sidecars".into(), pos2(200.0, 200.0));
        h.run_steps(2);
        assert_eq!(
            h.state()
                .sidecars_dialog
                .as_ref()
                .unwrap()
                .preview
                .created
                .len(),
            2,
            "tous les logiciels installés : .rrdata et .pp3 de la photo notée"
        );
        h.get_by_role(egui::accesskit::Role::ComboBox).click();
        h.run_steps(2);
        assert!(
            h.query_by_label(&t!("sidecars-format", engine = "ART", id = "arp"))
                .is_none(),
            "ART absent : pas proposé"
        );
        h.get_by_label(&t!("sidecars-format", engine = "RapidRAW", id = "rrdata"))
            .click();
        h.run_steps(2);
        let dialog = h.state().sidecars_dialog.as_ref().unwrap();
        assert_eq!(dialog.choice, Some("rrdata"));
        assert_eq!(dialog.preview.created.len(), 1);
        assert_eq!(dialog.preview.skipped, 2, "deux photos sans note");
        h.get_by_label(&t!("sidecars-go")).click();
        h.run_steps(2);
        assert!(h.state().sidecars_dialog.is_none());
        assert_eq!(
            tri::rrdata::read(&photos.join("img0.jpg.rrdata"))
                .unwrap()
                .stars,
            3
        );
        assert!(!photos.join("img1.jpg.rrdata").exists());
        assert!(h.state().notice.is_some(), "bilan dans la barre d'état");
        // Réécrire (31/10/2026) : les deux sidecars d'img0 existent, prévenu, réécrits.
        let images: Vec<PathBuf> = h.state().files.iter().map(|f| f.path.clone()).collect();
        h.state_mut()
            .open_sidecars_dialog(images, "sidecars".into(), pos2(200.0, 200.0));
        h.run_steps(2);
        assert_eq!(
            h.state()
                .sidecars_dialog
                .as_ref()
                .unwrap()
                .preview
                .created
                .len(),
            1,
            "il manque encore le .pp3"
        );
        h.get_by_label(&t!("sidecars-rewrite")).click();
        h.run_steps(2);
        let dialog = h.state().sidecars_dialog.as_ref().unwrap();
        assert!(dialog.rewrite);
        assert_eq!(dialog.preview.rewritten.len(), 2, "XMP et .rrdata d'img0");
        h.get_by_label(&t!("sidecars-rewrite-warning", n = 2));
        h.get_by_label(&t!("sidecars-go")).click();
        h.run_steps(2);
        assert!(h.state().sidecars_dialog.is_none());
        assert_eq!(
            tri::rrdata::read(&photos.join("img0.jpg.rrdata"))
                .unwrap()
                .stars,
            3
        );
    }

    #[test]
    fn the_last_folder_is_reopened_without_an_argument() {
        let dir = tempfile::tempdir().unwrap();
        let photos = dir.path().join("séance");
        std::fs::create_dir(&photos).unwrap();
        image::RgbImage::new(8, 8)
            .save(photos.join("a.jpg"))
            .unwrap();
        let settings = |reopen: bool| {
            let mut s = AppSettings::default();
            s.cache.dir = Some(dir.path().join("cache"));
            s.data.dir = Some(dir.path().join("data"));
            s.places.watch_ms = 0;
            s.gui.reopen_last = reopen;
            s
        };
        // Premier lancement, sur le dossier : il est mémorisé.
        let s = settings(true);
        let p = photos.clone();
        let _first = Harness::builder()
            .with_size(vec2(1000.0, 700.0))
            .build_eframe(move |_cc| TriApp::new(Some(p), s, None));
        // Sans argument : rouvert.
        let s = settings(true);
        let again = Harness::builder()
            .with_size(vec2(1000.0, 700.0))
            .build_eframe(move |_cc| TriApp::new(None, s, None));
        assert_eq!(again.state().folder.dir, photos);
        // Réglage désactivé : aucun dossier.
        let s = settings(false);
        let off = Harness::builder()
            .with_size(vec2(1000.0, 700.0))
            .build_eframe(move |_cc| TriApp::new(None, s, None));
        assert!(off.state().folder.is_none());
        // Disque débranché (dossier disparu) : dit au centre, rouvert à son retour (#66).
        let away = dir.path().join("débranché");
        std::fs::rename(&photos, &away).unwrap();
        let s = settings(true);
        let mut gone = Harness::builder()
            .with_size(vec2(1000.0, 700.0))
            .build_eframe(move |_cc| TriApp::new(None, s, None));
        gone.run_steps(3);
        assert!(gone.state().folder.is_none());
        assert!(gone.query_by_label_contains("n'est plus là").is_some());
        assert!(gone.query_by_label_contains("séance").is_some(), "son nom");
        std::fs::rename(&away, &photos).unwrap();
        gone.state_mut().reopen_missing_last();
        assert_eq!(gone.state().folder.dir, photos, "rebranché : rouvert");
        // Un autre dossier choisi entre-temps : pas de retour en arrière.
        std::fs::rename(&photos, &away).unwrap();
        let s = settings(true);
        let mut other = Harness::builder()
            .with_size(vec2(1000.0, 700.0))
            .build_eframe(move |_cc| TriApp::new(None, s, None));
        let elsewhere = dir.path().join("ailleurs");
        std::fs::create_dir(&elsewhere).unwrap();
        other.state_mut().open_folder(&elsewhere);
        std::fs::rename(&away, &photos).unwrap();
        other.state_mut().reopen_missing_last();
        assert_eq!(
            other.state().folder.dir,
            elsewhere,
            "on reste où on est allé"
        );
    }

