    #[test]
    fn filters_and_sort_are_kept_per_folder() {
        // Demandé le 30/10/2026 : d'un lancement à l'autre, par dossier
        // (`[gui] remember_folder_view`).
        let (mut h, dir) = harness();
        let photos = dir.path().join("photos");
        let other = dir.path().join("autre");
        std::fs::create_dir(&other).unwrap();
        image::RgbImage::new(8, 8)
            .save(other.join("x.jpg"))
            .unwrap();
        h.run_steps(3);
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::Num2, Modifiers::NONE);
        let rule = h.state().notes_rule.clone();
        assert!(rule.stars.is_some(), "filtre posé");
        h.state_mut().set_order(tri::sort::Order {
            key: tri::sort::SortKey::Modified,
            descending: true,
        });
        h.run_steps(2);
        let open = |h: &mut Harness<'_, TriApp>, dir: &Path| {
            h.state_mut().open_folder(dir);
            let dir = dir.to_path_buf();
            run_until(h, move |app| app.folder.dir == dir && app.opening.is_none());
            h.run_steps(2);
        };
        open(&mut h, &other);
        assert_eq!(
            h.state().notes_rule,
            NotesRule::default(),
            "autre dossier : rien"
        );
        open(&mut h, &photos);
        assert_eq!(h.state().notes_rule, rule, "repris");
        assert_eq!(h.state().order.key, tri::sort::SortKey::Modified);
        assert!(h.state().order.descending);
        // Rendu des vignettes par dossier (31/10/2026) : un dossier sans rien de retenu
        // reprend celui de la configuration, pas celui du dossier précédent.
        use crate::grid_render::GridRender;
        h.state_mut().set_grid_render(GridRender::LibRaw);
        h.run_steps(2);
        open(&mut h, &other);
        assert_eq!(h.state().grid_render, GridRender::Embedded, "configuration");
        open(&mut h, &photos);
        assert_eq!(h.state().grid_render, GridRender::LibRaw, "repris");
        // Réglage coupé : rien de repris, les filtres restent ceux du moment.
        h.state_mut().gui.remember_folder_view = false;
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::Num0, Modifiers::NONE);
        let now = h.state().notes_rule.clone();
        open(&mut h, &other);
        open(&mut h, &photos);
        assert_eq!(h.state().notes_rule, now);
    }

    #[test]
    fn the_filter_bar_shows_and_hides_with_shift_f() {
        let (mut h, _dir) = harness();
        // Fenêtre étroite, panneaux ouverts : la fin de la barre (effacer) reste dans la
        // partie visible et se clique (CI Linux, 27/10/2026 : elle glissait sous le
        // panneau de droite).
        h.set_size(vec2(700.0, 700.0));
        // Histogramme du panneau de droite d'abord : en arrivant, il pousse les cases RAW
        // et JPEG vers le bas, et le clic tombait à côté (CI Windows, 28/10/2026).
        run_until(&mut h, |app| app.meta_has_histogram);
        h.run_steps(3);
        assert!(
            h.query_by_label("Effacer").is_some(),
            "barre visible par défaut"
        );
        leader(&mut h, &[(Key::K, Modifiers::SHIFT)]);
        assert!(h.query_by_label("Effacer").is_none());
        leader(&mut h, &[(Key::K, Modifiers::SHIFT)]);
        // Deux interrupteurs : JPEG éteint, les RAW seuls ; rallumé, tout ; RAW éteint,
        // les JPEG seuls ; le dernier allumé ne s'éteint pas.
        click_settled(&mut h, "JPEG");
        h.run_steps(3);
        assert_eq!(
            h.state().filter,
            KindFilter::RawOnly,
            "clic : même action que le clavier"
        );
        click_settled(&mut h, "JPEG");
        h.run_steps(3);
        assert_eq!(h.state().filter, KindFilter::All);
        click_settled(&mut h, "RAW");
        h.run_steps(3);
        assert_eq!(h.state().filter, KindFilter::FlatOnly);
        click_settled(&mut h, "JPEG");
        h.run_steps(3);
        assert_eq!(
            h.state().filter,
            KindFilter::FlatOnly,
            "un des deux reste allumé"
        );
        click_settled(&mut h, "Effacer");
        h.run_steps(3);
        assert_eq!(h.state().filter, KindFilter::All);
    }

