    #[test]
    fn pauses_and_progression_tune_the_stacks() {
        // Six images de même contenu, à peine différentes d'une voisine à l'autre ; prises
        // à 1 s d'intervalle, avec une pause de 30 s au milieu (#306).
        let names = ["a1.jpg", "a2.jpg", "a3.jpg", "b1.jpg", "b2.jpg", "b3.jpg"];
        // Distances toutes différentes (1 à 5 bits de composition : 0,008 à 0,039).
        let img = image::RgbImage::from_pixel(8, 8, image::Rgb([90, 90, 90]));
        let (mut h, dir) = harness_images(names.iter().map(|n| (*n, img.clone())).collect());
        h.state_mut().stacking = true;
        h.state_mut().settings.similarity.auto = false;
        h.state_mut().settings.similarity.threshold = 0.05;
        let files = h.state().files.clone();
        for (i, f) in files.iter().enumerate() {
            let sig = tri::similarity::Signature {
                shape: (1u64 << (i * (i + 1) / 2)) - 1,
                colors: [90; 48],
                time: Some(i as i64 + if i >= 3 { 30 } else { 0 }),
            };
            h.state_mut().signatures.insert(f.path.clone(), sig);
        }
        let stacks = |h: &mut Harness<'static, TriApp>| {
            h.state_mut().stacks_dirty = true;
            h.run_steps(2);
            h.state().stacks.count()
        };
        assert_eq!(
            stacks(&mut h),
            1,
            "au centre, la pause ne suffit pas à couper"
        );
        h.state_mut().group_pauses = 1.0;
        assert_eq!(stacks(&mut h), 2, "pauses importantes : coupées");
        h.state_mut().group_pauses = -1.0;
        assert_eq!(stacks(&mut h), 1, "pauses ignorées");
        // Progression : à fond à gauche, tout ensemble quelle qu'elle soit (#306) ; à
        // mi-chemin, plus douce (moins de liens joints) au-delà de 1.
        h.state_mut().settings.similarity.auto_min_links = 2;
        h.state_mut().settings.similarity.threshold = 0.001;
        assert_eq!(stacks(&mut h), 0, "au centre : aucune pile");
        h.state_mut().group_strictness = -1.0;
        h.state_mut().group_curve = 4.0;
        assert_eq!(stacks(&mut h), 1, "à fond à gauche : tout ensemble");
        h.state_mut().group_strictness = -0.5;
        let steep = h.state().group_threshold();
        h.state_mut().group_curve = 1.0;
        assert!(
            h.state().group_threshold() > steep,
            "λ = 1 : plus de liens joints"
        );
        h.state_mut().group_strictness = -1.0;
        h.state_mut().group_curve = 3.0;
        // La fenêtre (Ctrl+G) montre les deux curseurs ; à sa fermeture, retenus pour le
        // dossier.
        press(&mut h, Key::S, Modifiers::CTRL);
        h.run_steps(2);
        for label in [t!("groups-pauses"), t!("groups-curve")] {
            assert!(h.query_by_label_contains(&label).is_some(), "{label}");
        }
        press(&mut h, Key::Escape, Modifiers::NONE);
        h.run_steps(2);
        assert!(!h.state().group_dialog);
        let data = h.state().settings.data_dir().unwrap();
        let folder = h.state().folder.dir.clone();
        assert_eq!(tri::similarity::folder_pauses(&data, &folder), Some(-1.0));
        assert_eq!(
            tri::similarity::folder_strictness(&data, &folder),
            Some(-1.0),
            "la sévérité aussi, fermée au clavier"
        );
        assert_eq!(tri::similarity::folder_curve(&data, &folder), Some(3.0));
        drop(dir);
    }

    #[test]
    fn the_grid_starts_without_stacks_unless_asked() {
        assert!(!crate::settings::GridSettings::default().stacks);
        let (h, _dir) = harness();
        assert!(!h.state().stacking, "grille non groupée par défaut");
        // Jamais les données de l'utilisateur : dossier temporaire, rien de rouvert.
        let dir = tempfile::tempdir().unwrap();
        let mut settings = AppSettings::default();
        settings.data.dir = Some(dir.path().join("data"));
        settings.cache.dir = Some(dir.path().join("cache"));
        settings.gui.reopen_last = false;
        settings.gui.grid.stacks = true;
        let app = TriApp::new(None, settings, None);
        assert!(app.stacking, "[gui.grid] stacks = true");
    }

    #[test]
    fn the_stack_is_a_sentence_for_d_y_and_parentheses() {
        // Issue n° 62 (choix de l'utilisateur) : `d)` / `y)` toute la pile, `(` / `)` son
        // début et sa fin ; Maj+Début / Maj+Fin en classique.
        let ramp = |tint: u8| {
            image::RgbImage::from_fn(64, 48, |x, _| image::Rgb([(x * tint as u32 / 63) as u8; 3]))
        };
        let images = vec![
            ("a1.jpg", ramp(255)),
            ("a2.jpg", ramp(250)),
            ("a3.jpg", ramp(245)),
        ];
        let (mut h, _dir) = harness_images(images);
        h.state_mut().stacking = true;
        let files = h.state().files.clone();
        let preview = tri::preview::Settings::default();
        let cancel = std::sync::atomic::AtomicBool::new(false);
        for f in &files {
            let sig = tri::preview::compute_signature(f, &preview, &cancel).unwrap();
            h.state_mut().signatures.insert(f.path.clone(), sig);
        }
        h.state_mut().stacks_dirty = true;
        // Délai de la touche ambiguë large : `y` attend le `)`.
        h.state_mut().sequencer = crate::actions::Sequencer::new(Duration::from_secs(60))
            .with_ambiguous(Duration::from_secs(60));
        h.run_steps(3);
        use_vim(&mut h);
        assert_eq!(h.state().stacks.count(), 1);
        let bracket = |h: &mut Harness<'_, TriApp>| {
            h.event(UiEvent::Text(")".into()));
            h.run_steps(3);
        };
        // d ) : corbeille pour les 3 images de la pile, cachées comprises.
        press(&mut h, Key::D, Modifiers::NONE);
        bracket(&mut h);
        assert!(
            h.query_by_label_contains("3 fichiers").is_some(),
            "suppression de la pile"
        );
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(h.state().file_dialog.is_none());
        // y ) : copie de la pile.
        press(&mut h, Key::Y, Modifiers::NONE);
        assert!(h.state().file_dialog.is_none(), "y attend la suite");
        bracket(&mut h);
        assert!(h.query_by_label_contains("3 images vers").is_some());
        press(&mut h, Key::Escape, Modifiers::NONE);
        // Plein écran, mode pile : `)` la dernière, `(` la première ; Maj+Fin, Maj+Début.
        // `(` et `)` commencent aussi `((` / `))` (31/10/2026) : sans délai d'attente ici.
        h.state_mut().sequencer =
            crate::actions::Sequencer::new(Duration::from_secs(60)).with_ambiguous(Duration::ZERO);
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        bracket(&mut h);
        assert_eq!(h.state().selected, 2, "fin de pile");
        h.event(UiEvent::Text("(".into()));
        h.run_steps(3);
        assert_eq!(h.state().selected, 0, "début de pile");
        // Maj+Fin / Maj+Début : le profil classique.
        h.state_mut().keymap = crate::actions::Keymap::default()
            .with_leader("Ctrl+b")
            .unwrap();
        press(&mut h, Key::End, Modifiers::SHIFT);
        assert_eq!(h.state().selected, 2);
        press(&mut h, Key::Home, Modifiers::SHIFT);
        assert_eq!(h.state().selected, 0);
        // Ctrl+Maj+S : entrer par la première photo, puis de nouveau par la couverture.
        let before = h.state().stack_enter;
        press(&mut h, Key::S, Modifiers::CTRL | Modifiers::SHIFT);
        assert_ne!(h.state().stack_enter, before);
        // Rien ne bouge à l'écran : un message dit ce qui a changé.
        assert!(
            h.state()
                .hint
                .as_ref()
                .is_some_and(|h| h.contains(&t!("stack-enter-first"))
                    || h.contains(&t!("stack-enter-cover"))),
            "{:?}",
            h.state().hint
        );
        press(&mut h, Key::S, Modifiers::CTRL | Modifiers::SHIFT);
        assert_eq!(h.state().stack_enter, before);
        press(&mut h, Key::Escape, Modifiers::NONE);
        // `c` sur la pile repliée, sans sélection : ses photos côte à côte (#52) ; Échap
        // revient à la grille, sur sa couverture.
        assert_eq!(h.state().mode, Mode::Grid);
        type_text(&mut h, "=");
        assert_eq!(h.state().mode, Mode::Compare);
        assert_eq!(h.state().compare.len(), 3, "toute la pile");
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Grid);
        let cover = h.state().stacks.visible(h.state().selected);
        assert_eq!(h.state().selected, cover, "la couverture, visible");
        // Piles désactivées : expliqué, rien d'autre (`d` attend de nouveau sa suite).
        use_vim(&mut h);
        h.state_mut().sequencer = crate::actions::Sequencer::new(Duration::from_secs(60))
            .with_ambiguous(Duration::from_secs(60));
        h.state_mut().stacking = false;
        press(&mut h, Key::D, Modifiers::NONE);
        bracket(&mut h);
        assert!(h.state().file_dialog.is_none());
        assert!(
            h.state()
                .notice
                .as_ref()
                .unwrap()
                .0
                .contains("Pas de pile ici")
        );
    }

    #[test]
    fn a_refilter_keeps_the_region_shown() {
        // Issue n° 100 : sélection en haut, grille défilée plus bas à la molette ; un
        // refiltrage (réglage d'un curseur de filtre) ne ramène pas au début.
        let names: Vec<String> = (0..60).map(|i| format!("i{i:02}.jpg")).collect();
        let images = names
            .iter()
            .map(|n| (n.as_str(), image::RgbImage::new(16, 16)))
            .collect();
        let (mut h, _dir) = harness_images(images);
        h.run_steps(3);
        // Défile vers le bas (rangée de l'image 40 en haut), sélection laissée sur 0.
        h.state_mut().selected = 40;
        h.state_mut().reveal = Some(Reveal::Top);
        h.run_steps(3);
        h.state_mut().selected = 0;
        h.run_steps(2);
        let before = h.state().scroll_offset;
        assert!(before > 0.0, "défilée");
        h.state_mut().refilter(Reveal::Minimal);
        h.run_steps(3);
        assert_eq!(h.state().scroll_offset, before, "même région");
        // La sélection visible : on la montre, comme avant.
        h.state_mut().reveal = Some(Reveal::Top);
        h.run_steps(3);
        h.state_mut().refilter(Reveal::Minimal);
        h.run_steps(3);
        assert_eq!(h.state().scroll_offset, 0.0, "sur la sélection");
    }

    #[test]
    fn a_single_photo_is_a_stack_to_compare() {
        // #167 : piles actives, `c` sur une photo seule (pile d'une image) la compare.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        // Sans piles ni sélection : toutes les images (07/11/2026).
        type_text(&mut h, "=");
        assert_eq!(h.state().mode, Mode::Compare);
        assert_eq!(h.state().compare.len(), 3);
        act(&mut h, Action::Back);
        assert_eq!(h.state().mode, Mode::Grid);
        h.state_mut().stacking = true;
        h.state_mut().stacks_dirty = true;
        // L'image courante en surbrillance (curseur montré) : sa pile.
        h.state_mut().cursor_hidden = false;
        h.run_steps(2);
        type_text(&mut h, "=");
        assert_eq!(h.state().mode, Mode::Compare);
        assert_eq!(h.state().compare.len(), 1);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Grid);
    }

    #[test]
    fn c_compares_a_photo_with_its_developments() {
        // 31/10/2026 : sans sélection, `c` sur une photo qui a des développements les
        // compare côte à côte (JPEG boîtier et clone darktable ici) ; Échap revient à la
        // grille sur le développement actif, montré à la place de la couverture.
        // Trois photos dissemblables (img0 unie, img1 et img2 en dégradés) : piles de
        // rafale actives, seuls img0 et son clone (mêmes pixels) se regroupent.
        let ramp = |vertical: bool, tint: [u8; 3]| {
            image::RgbImage::from_fn(64, 48, |x, y| {
                let v = if vertical { y * 255 / 47 } else { x * 255 / 63 } as u16;
                image::Rgb(tint.map(|c| (v * c as u16 / 255) as u8))
            })
        };
        let (mut h, dir) = harness_images(vec![
            (
                "img0.jpg",
                image::RgbImage::from_pixel(64, 48, image::Rgb([30, 100, 160])),
            ),
            ("img1.jpg", ramp(false, [255, 40, 40])),
            ("img2.jpg", ramp(true, [40, 255, 40])),
        ]);
        h.run_steps(3);
        let photos = dir.path().join("photos");
        std::fs::write(
            photos.join("img0_01.jpg.xmp"),
            r#"<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description rdf:about="" xmlns:darktable="http://darktable.sf.net/" darktable:xmp_version="5" darktable:history_end="1"/></rdf:RDF></x:xmpmeta>"#,
        )
        .unwrap();
        // Les développements des seuls logiciels actifs (07/11/2026).
        h.state_mut().developers = fake_darktable();
        h.state_mut().reload_folder(None);
        h.state_mut()
            .set_grid_render(crate::grid_render::GridRender::Cover);
        let clone = photos.join("img0@dt-01.jpg");
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 4);
        h.run_steps(2);
        let i = h
            .state()
            .files
            .iter()
            .position(|f| f.path == clone)
            .unwrap();
        assert_eq!(h.state().selected, i, "la couverture : le clone");
        assert!(!h.state().stacking, "piles de rafale inactives");
        type_text(&mut h, "=");
        assert_eq!(h.state().mode, Mode::Compare, "hint: {:?}", h.state().hint);
        assert_eq!(
            h.state().compare,
            vec![photos.join("img0.jpg"), clone.clone()],
            "la photo et son développement"
        );
        assert_eq!(
            selected_name(&h),
            "img0@dt-01.jpg",
            "l'image courante reste active"
        );
        press(&mut h, Key::ArrowLeft, Modifiers::NONE);
        assert_eq!(selected_name(&h), "img0.jpg");
        // Une pile recalculée pendant la comparaison (une vignette arrive) ne ramène pas
        // l'image active à la couverture (vu sur Windows, plus lent).
        h.state_mut().stacks_dirty = true;
        h.run_steps(2);
        assert_eq!(selected_name(&h), "img0.jpg", "toujours l'image active");
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Grid);
        h.run_steps(2);
        assert_eq!(selected_name(&h), "img0.jpg", "on reste sur l'image active");
        assert!(
            h.state().stacks.folded_count(i - 1).is_some(),
            "montrée à la place de la couverture, pile toujours repliée"
        );
        // Piles de rafale actives : la rafale réduite à la photo et son clone, ce sont
        // encore les développements qu'on compare (pas une seule image).
        h.state_mut().stacking = true;
        // Empreintes calculées directement (le moteur du banc de test ne les fait pas) ; le
        // clone a les pixels de sa photo.
        let files = h.state().files.clone();
        let preview = tri::preview::Settings::default();
        let cancel = std::sync::atomic::AtomicBool::new(false);
        for f in &files {
            let source = tri::media::source(&f.path).into_owned();
            let sig = tri::preview::compute_signature(
                &MediaFile {
                    path: source,
                    ..f.clone()
                },
                &preview,
                &cancel,
            )
            .unwrap();
            h.state_mut().signatures.insert(f.path.clone(), sig);
        }
        h.state_mut().stacks_dirty = true;
        h.run_steps(3);
        assert_eq!(
            h.state().stacks.groups(),
            3,
            "img0 et son clone, img1, img2"
        );
        type_text(&mut h, "=");
        assert_eq!(h.state().mode, Mode::Compare);
        assert_eq!(
            h.state().compare.len(),
            2,
            "shown: {:?}",
            h.state().stacks.shown
        );
        press(&mut h, Key::Escape, Modifiers::NONE);
        // Une rafale repliée (ici : toutes les images en une pile) : ses photos, chacune
        // par la couverture de sa pile de développements, jamais deux fois la même photo.
        let all: HashSet<PathBuf> = h.state().files.iter().map(|f| f.path.clone()).collect();
        h.state_mut().stack_only = Some(all);
        h.state_mut().stacks_dirty = true;
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 1, "une seule pile repliée");
        type_text(&mut h, "=");
        assert_eq!(h.state().mode, Mode::Compare);
        let compared: Vec<String> = h.state().compare.iter().map(|p| file_name(p)).collect();
        assert_eq!(compared, ["img0.jpg", "img1.jpg", "img2.jpg"]);
    }

    #[test]
    fn similar_images_stack_and_unstack() {
        // Deux rafales de 3 images : des dégradés horizontaux, puis verticaux, de teintes
        // différentes ; entre elles, rien de commun.
        let ramp = |vertical: bool, tint: [u8; 3]| {
            image::RgbImage::from_fn(64, 48, |x, y| {
                let v = if vertical { y * 255 / 47 } else { x * 255 / 63 } as u16;
                image::Rgb(tint.map(|c| (v * c as u16 / 255) as u8))
            })
        };
        let images = vec![
            ("a1.jpg", ramp(false, [255, 255, 255])),
            ("a2.jpg", ramp(false, [250, 250, 250])),
            ("a3.jpg", ramp(false, [245, 245, 245])),
            ("b1.jpg", ramp(true, [255, 80, 20])),
            ("b2.jpg", ramp(true, [250, 80, 20])),
            ("b3.jpg", ramp(true, [245, 80, 20])),
        ];
        let (mut h, _dir) = harness_images(images);
        h.state_mut().stacking = true;
        h.state_mut().settings.similarity.background = true;
        // Empreintes calculées directement (le moteur du banc de test ne les fait pas).
        let files = h.state().files.clone();
        let preview = tri::preview::Settings::default();
        let cancel = std::sync::atomic::AtomicBool::new(false);
        for f in &files {
            let sig = tri::preview::compute_signature(f, &preview, &cancel).unwrap();
            h.state_mut().signatures.insert(f.path.clone(), sig);
        }
        h.state_mut().stacks_dirty = true;
        h.run_steps(3);
        assert_eq!(h.state().stacks.shown.len(), 2, "deux piles repliées");
        assert_eq!(h.state().stacks.count(), 2);
        // `f c` : seulement la pile courante, dépliée ; encore : tout (#52).
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::S, Modifiers::NONE);
        assert_eq!(h.state().files.len(), 3, "une pile");
        assert_eq!(h.state().stacks.shown.len(), 3, "dépliée");
        assert!(h.state().filter_summary().contains("pile de 3"));
        // Une seule pile, quel que soit le seuil (#163 : regroupées à part, ses photos se
        // coupaient en deux piles).
        let similarity = h.state().settings.similarity;
        h.state_mut().settings.similarity.auto = false;
        h.state_mut().settings.similarity.threshold = 0.0;
        h.state_mut().stacks_dirty = true;
        h.run_steps(2);
        assert_eq!(h.state().stacks.count(), 1, "une seule pile");
        h.state_mut().settings.similarity = similarity;
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::S, Modifiers::NONE);
        assert_eq!(h.state().files.len(), 6, "tout");
        h.run_steps(2);
        // Repliée avant `f c` : repliée de nouveau en sortant (retour du 25/10/2026).
        assert_eq!(h.state().stacks.shown.len(), 2, "pile repliée de nouveau");
        // Bouton de la pile dans la barre des filtres (06/11/2026) : comme `f c`.
        let tip = h.state().action_tip(Action::FilterStack);
        h.get_by_label(&tip).click();
        h.run_steps(2);
        assert_eq!(h.state().files.len(), 3, "bouton : une pile");
        h.get_by_label(&tip).click();
        h.run_steps(2);
        assert_eq!(h.state().files.len(), 6, "bouton encore : tout");
        h.state_mut().stacking = false;
        h.run_steps(2);
        assert!(
            h.query_by_label(&tip).is_none(),
            "sans piles, pas de bouton"
        );
        h.state_mut().stacking = true;
        h.state_mut().stacks_dirty = true;
        h.run_steps(2);
        // Dépliée avant (s) : elle le reste.
        type_text(&mut h, "(");
        type_text(&mut h, "(");
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::S, Modifiers::NONE);
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::S, Modifiers::NONE);
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 4, "pile restée dépliée");
        h.state_mut().expanded.clear();
        h.state_mut().stacks_dirty = true;
        h.run_steps(2);
        // Toutes brûlées : pas de badge d'écrêtage sur une pile repliée (#75).
        for f in &files {
            h.state_mut()
                .clip_summary
                .insert(f.path.clone(), (1.0, 0.0));
        }
        h.run_steps(2);
        let over = t!("badge-over", percent = tri::i18n::decimal(100.0, 1));
        assert_eq!(h.query_all_by_label(&over).count(), 0, "piles repliées");
        // La flèche droite saute les images cachées : de la première pile à la seconde.
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert!(selected_name(&h).starts_with('b'), "{}", selected_name(&h));
        // s déplie la pile ; Maj+S déplie / replie tout.
        type_text(&mut h, "(");
        type_text(&mut h, "(");
        assert_eq!(h.state().stacks.shown.len(), 4);
        press(&mut h, Key::S, Modifiers::SHIFT);
        assert_eq!(h.state().stacks.shown.len(), 2, "tout replié");
        press(&mut h, Key::S, Modifiers::SHIFT);
        assert_eq!(h.state().stacks.shown.len(), 6, "tout déplié");
        h.run_steps(2);
        assert!(
            h.query_all_by_label(&over).count() > 0,
            "dépliées : les badges"
        );
        press(&mut h, Key::S, Modifiers::SHIFT);
        h.state_mut().expanded.clear();
        h.state_mut().stacks_dirty = true;
        h.run_steps(2);
        // Plein écran, mode pile (Ctrl+S) : → dans la pile, arrêt au bout ; ↓ la pile
        // suivante ; Entrée choisit la préférée, qui devient la couverture.
        let pos = |name: &str| files.iter().position(|f| f.path.ends_with(name)).unwrap();
        h.state_mut().select(pos("a1.jpg"));
        h.state_mut().chosen.clear();
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        assert!(h.state().stacking, "piles actives : en plein écran aussi");
        let start = h.state().selected;
        let range = h.state().stacks.range_of(start).cloned().unwrap();
        // Avance automatique : la photo suivante de la pile, pas la pile suivante (#60).
        h.state_mut().select(range.start);
        h.state_mut().auto_advance = true;
        press(&mut h, Key::Num1, Modifiers::NONE);
        assert_eq!(h.state().selected, range.start + 1, "{}", selected_name(&h));
        // En fin de pile, on y reste (comme →, `stack_wrap` désactivé).
        h.state_mut().select(range.end - 1);
        press(&mut h, Key::Num1, Modifiers::NONE);
        assert_eq!(h.state().selected, range.end - 1, "{}", selected_name(&h));
        // Avec `stack_advance_next` : la première photo de la pile suivante, même si
        // `stack_wrap` est actif.
        h.state_mut().gui.view.stack_advance_next = true;
        h.state_mut().gui.view.stack_wrap = true;
        press(&mut h, Key::Num1, Modifiers::NONE);
        assert_eq!(h.state().selected, range.end, "{}", selected_name(&h));
        assert!(selected_name(&h).starts_with('b'), "pile suivante");
        h.state_mut().gui.view.stack_advance_next = false;
        h.state_mut().gui.view.stack_wrap = false;
        h.state_mut().select(range.end - 1);
        h.state_mut().auto_advance = false;
        for _ in 0..5 {
            press(&mut h, Key::ArrowRight, Modifiers::NONE);
        }
        assert_eq!(h.state().selected, range.end - 1, "arrêt en fin de pile");
        assert!(h.query_by_label_contains("pile : 3 / 3").is_some());
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(
            h.state().stacks.cover_of(start),
            Some(range.end - 1),
            "préférée"
        );
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        assert!(selected_name(&h).starts_with('b'), "pile suivante");
        press(&mut h, Key::ArrowUp, Modifiers::NONE);
        assert_eq!(h.state().selected, range.end - 1, "retour : sa couverture");
        // `stack_enter = "first"` : la première photo de la pile, pas sa couverture (#62).
        h.state_mut().stack_enter = crate::settings::StackEnter::First;
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        let next = h
            .state()
            .stacks
            .range_of(h.state().selected)
            .cloned()
            .unwrap();
        assert_eq!(
            h.state().selected,
            next.start,
            "première de la pile suivante"
        );
        press(&mut h, Key::ArrowUp, Modifiers::NONE);
        assert_eq!(
            h.state().selected,
            range.start,
            "première de la pile d'avant"
        );
        // Depuis la grille aussi (retour du 26/10/2026) : Entrée sur la pile repliée, sa
        // première photo plutôt que sa couverture.
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Grid);
        h.state_mut().select(range.end - 1);
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        assert_eq!(h.state().selected, range.start, "depuis la grille");
        h.state_mut().stack_enter = crate::settings::StackEnter::Cover;
        h.state_mut().select(range.end - 1);
        // Ctrl+S : plus de piles ; → passe à la photo suivante, toutes visibles.
        press(&mut h, Key::S, Modifiers::NONE);
        assert!(!h.state().stacking);
        h.run_steps(2);
        let before = h.state().selected;
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(h.state().selected, before + 1, "de photo en photo");
        press(&mut h, Key::S, Modifiers::NONE);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Grid);
        // Ctrl+G : la fenêtre ; seuil nul : plus de piles.
        press(&mut h, Key::S, Modifiers::CTRL);
        assert!(h.state().group_dialog);
        h.state_mut().settings.similarity.auto = false;
        h.state_mut().settings.similarity.threshold = 0.0;
        h.state_mut().stacks_dirty = true;
        h.run_steps(2);
        assert_eq!(
            h.state().stacks.count(),
            0,
            "seuil nul : chaque image seule"
        );
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(!h.state().group_dialog);
    }

    #[test]
    fn zoom_steps_pinch_and_loupe() {
        let (mut h, _dir) = harness_with(4000, 3000);
        h.run_steps(3);
        press(&mut h, Key::Enter, Modifiers::NONE);
        run_until(&mut h, |app| app.last_shown.1.is_some());
        // + : palier au-dessus de l'ajusté ; * : 100 % ; - : palier en dessous ; / : ajusté.
        h.event(UiEvent::Text("+".into()));
        h.run_steps(3);
        assert!(h.state().zoom.is_some(), "zoomé");
        let first = h.state().zoom_scale;
        assert!(
            h.state().gui.zoom.steps.contains(&first),
            "un palier : {first}"
        );
        h.event(UiEvent::Text("*".into()));
        h.run_steps(3);
        assert_eq!(h.state().zoom_scale, 1.0);
        // Dans la barre d'état (et le bouton 1:1).
        assert!(
            h.query_all_by_label_contains("100 %").next().is_some(),
            "affiché"
        );
        h.event(UiEvent::Text("-".into()));
        h.run_steps(3);
        assert!(h.state().zoom_scale < 1.0 || h.state().zoom.is_none());
        h.event(UiEvent::Text("/".into()));
        h.run_steps(3);
        assert!(h.state().zoom.is_none(), "ajusté");
        // - depuis l'ajusté : sous l'ajusté, l'image plus petite que l'écran.
        h.event(UiEvent::Text("-".into()));
        h.run_steps(3);
        assert!(h.state().zoom.is_some(), "dézoomé");
        assert!(h.state().zoom_scale < h.state().fit_scale, "sous l'ajusté");
        h.event(UiEvent::Text("/".into()));
        h.run_steps(3);
        // Pincer au-dessus de l'image : zoom continu.
        let center = h.ctx.content_rect().center();
        h.hover_at(center);
        h.event(UiEvent::Zoom(3.0));
        h.run_steps(3);
        assert!(h.state().zoom.is_some(), "pincé : zoomé");
        let pinched = h.state().zoom_scale;
        assert!(
            pinched > h.state().fit_scale,
            "au-delà de l'ajusté : {pinched}"
        );
        h.event(UiEvent::Zoom(1000.0));
        h.run_steps(3);
        assert_eq!(h.state().zoom_scale, h.state().gui.zoom.max, "plafonné");
        // Loupe : `t` maintenue (défaut), en vue ajustée ; Maj ne la montre plus.
        press(&mut h, Key::Z, Modifiers::NONE);
        if h.state().zoom.is_some() {
            press(&mut h, Key::Z, Modifiers::NONE);
        }
        h.state_mut().gui.zoom.loupe_delay_ms = 0;
        h.event(UiEvent::ModifiersChanged(Modifiers::SHIFT));
        h.hover_at(center + vec2(1.0, 0.0));
        h.run_steps(3);
        assert!(!h.state().loupe_on, "Maj : plus de loupe");
        h.event(UiEvent::ModifiersChanged(Modifiers::NONE));
        let key = |pressed| UiEvent::Key {
            key: Key::M,
            physical_key: None,
            pressed,
            repeat: false,
            modifiers: Modifiers::NONE,
        };
        h.event(key(true));
        h.run_steps(3);
        assert!(h.state().loupe_on, "loupe");
        h.event(key(false));
        h.run_steps(3);
        assert!(!h.state().loupe_on, "lâchée");
    }

