    fn run_until(h: &mut Harness<'_, TriApp>, done: impl Fn(&TriApp) -> bool) {
        // Large : les machines d'intégration continue sont plus lentes (20 s ne suffisaient
        // pas au zoom sur une image de 4000 × 3000) ; rapide quand tout va bien.
        let deadline = Instant::now() + Duration::from_secs(60);
        while !done(h.state()) {
            assert!(Instant::now() < deadline, "délai dépassé");
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
    }

    /// Clique l'élément de libellé `label` une fois sa place stable (même rectangle sur
    /// plusieurs images de suite) : un résultat de fond arrivé entre la lecture de la
    /// place et le clic décalait la mise en page, et le clic tombait à côté (CI Windows,
    /// 28/10/2026, deux fois).
    #[track_caller]
    fn click_settled(h: &mut Harness<'_, TriApp>, label: &str) {
        const STABLE: usize = 5;
        let deadline = Instant::now() + Duration::from_secs(60);
        let mut last = h.get_by_label(label).rect();
        let mut same = 0;
        while same < STABLE {
            assert!(Instant::now() < deadline, "« {label} » ne se stabilise pas");
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
            let rect = h.get_by_label(label).rect();
            same = if rect == last { same + 1 } else { 0 };
            last = rect;
        }
        h.get_by_label(label).click();
    }

    /// Attend qu'un élément de libellé `label` soit affiché (une fenêtre egui peut demander
    /// une image de plus pour apparaître, plus sur une machine d'intégration continue lente).
    #[track_caller]
    fn wait_for_label(h: &mut Harness<'_, TriApp>, label: &str) {
        let deadline = Instant::now() + Duration::from_secs(60);
        while h.query_by_label(label).is_none() {
            assert!(Instant::now() < deadline, "« {label} » jamais affiché");
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
    }

    #[test]
    fn a_slow_folder_opens_in_the_background_and_can_be_cancelled() {
        // Retour du 29/10/2026 (NAS) : l'interface restait figée pendant la lecture du
        // dossier, sans rien dire ni moyen d'annuler. Attente nulle : la liste se lit
        // toujours en fond ici.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = h.state().folder.dir.clone();
        let other = dir.path().join("autre");
        std::fs::create_dir(&other).unwrap();
        image::RgbImage::from_pixel(8, 8, image::Rgb([9, 9, 9]))
            .save(other.join("x.jpg"))
            .unwrap();
        h.state_mut().open_wait_override = Some(Duration::ZERO);
        // Annulée tout de suite : le dossier d'avant reste.
        h.state_mut().open_folder(&other);
        assert!(h.state().opening.is_some(), "lue en fond");
        h.state_mut().cancel_opening();
        h.run_steps(5);
        assert_eq!(h.state().folder.dir, photos);
        assert!(
            h.state()
                .notice
                .as_ref()
                .is_some_and(|(n, _)| n == "Ouverture de « autre » annulée.")
        );
        // Laissée finir : le dossier s'ouvre.
        h.state_mut().open_folder(&other);
        let deadline = Instant::now() + Duration::from_secs(30);
        while h.state().opening.is_some() {
            assert!(Instant::now() < deadline, "ouverture en fond");
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
        assert_eq!(h.state().folder.dir, std::path::absolute(&other).unwrap());
        assert_eq!(h.state().files.len(), 1);
        // La boîte d'attente, et Échap qui annule (liste qui n'arrive jamais).
        let (_tx, rx) = mpsc::channel();
        h.state_mut().opening = Some(Opening {
            dir: photos.clone(),
            result: rx,
            stop: Arc::new(AtomicBool::new(false)),
            found: Arc::new(AtomicUsize::new(12)),
        });
        h.run_steps(2);
        wait_for_label(&mut h, "Ouverture de « photos »…");
        wait_for_label(&mut h, "12 images trouvées");
        press(&mut h, Key::Escape, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().opening.is_none());
        assert_eq!(
            h.state().files.len(),
            1,
            "le dossier affiché n'a pas changé"
        );
    }

    #[test]
    fn histogram_zones_and_badges() {
        let (mut h, dir) = harness();
        // Une image entièrement blanche : saturée, donc badge et zones.
        let photos = dir.path().join("photos");
        image::RgbImage::from_pixel(64, 48, image::Rgb([255, 255, 255]))
            .save(photos.join("img9.jpg"))
            .unwrap();
        h.state_mut().open_folder(&photos);
        run_until(&mut h, |app| {
            (0..app.files.len()).all(|i| app.ready(i, Level::Exposure))
        });
        h.run_steps(3);
        let white = h
            .state()
            .files
            .iter()
            .position(|f| f.path.ends_with("img9.jpg"))
            .unwrap();
        let white_path = photos.join("img9.jpg");
        let (over, _) = h.state().clip_summary[&white_path];
        assert!(over > 0.99, "image blanche : {over}");
        assert!(over > h.state().gui.histogram.badge_over, "badge affiché");
        // Clic sur le badge : l'image choisie, le grand histogramme ouvert.
        assert!(!h.state().histogram_large);
        let percent = tri::i18n::decimal((over * 1000.0).round() / 10.0, 1);
        h.get_by_label(&t!("badge-over", percent = percent.clone()))
            .click();
        h.run_steps(3);
        assert!(h.state().histogram_large);
        assert_eq!(h.state().selected, white);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(!h.state().histogram_large);
        // f w : bien exposées, l'image blanche part (et les aplats à 0 sur un canal,
        // bouchés) ; f i : seulement elles ; l'entonnoir : tout.
        let n = h.state().files.len();
        let hist = h.state().gui.histogram;
        let badly: Vec<PathBuf> = h
            .state()
            .files
            .iter()
            .filter(|f| {
                let (o, u) = h.state().clip_summary[&f.path];
                o > hist.badge_over || u > hist.badge_under
            })
            .map(|f| f.path.clone())
            .collect();
        assert!(badly.contains(&white_path));
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::W, Modifiers::NONE);
        assert!(h.state().well_exposed);
        assert_eq!(h.state().files.len(), n - badly.len());
        // Plus de refiltrage ensuite (issue n° 10 : refiltrée sans fin, la grille revenait
        // sans cesse à la sélection et ne défilait plus).
        let generation = h.state().engine.as_ref().unwrap().generation;
        for _ in 0..30 {
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(20));
        }
        assert_eq!(h.state().engine.as_ref().unwrap().generation, generation);
        assert!(!h.state().files.iter().any(|f| badly.contains(&f.path)));
        // Curseurs « brûlé » / « bouché » avec le filtre ; tout à gauche, plus rien n'est
        // exclu (fonds noirs, issue n° 48), et plus de badge.
        // Les deux curseurs dans la section « Filtres » du panneau de droite
        // (réorganisation du 27/10/2026).
        h.run_steps(2);
        assert!(h.query_by_label(&t!("panel-clip-over")).is_some());
        assert!(h.query_by_label(&t!("panel-clip-under")).is_some());
        h.state_mut().clip_strictness = (-1.0, -1.0);
        h.state_mut().refilter(Reveal::Minimal);
        assert_eq!(h.state().files.len(), n);
        assert_eq!(h.state().clip_thresholds(), (1.0, 1.0));
        h.state_mut().clip_strictness = (0.0, 0.0);
        h.state_mut().refilter(Reveal::Minimal);
        assert_eq!(h.state().files.len(), n - badly.len());
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::I, Modifiers::NONE);
        let shown: Vec<_> = h.state().files.iter().map(|f| f.path.clone()).collect();
        assert_eq!(shown, badly, "inversé : les mal exposées");
        h.get_by_label("Effacer").click();
        h.run_steps(3);
        assert!(!h.state().well_exposed && !h.state().filter_inverted);
        assert_eq!(h.state().files.len(), n);
        let white = h
            .state()
            .files
            .iter()
            .position(|f| f.path == white_path)
            .unwrap();
        // Plein écran sur l'image blanche : histogramme et zones.
        h.state_mut().select(white);
        press(&mut h, Key::Enter, Modifiers::NONE);
        run_until(&mut h, |app| app.exposures.contains(&white_path));
        // Badge de l'écrêtage dans le bandeau aussi (issue n° 9) : grand histogramme.
        h.run_steps(2);
        assert!(!h.state().histogram_large);
        h.get_by_label(&t!("badge-over", percent = percent)).click();
        h.run_steps(3);
        assert!(
            h.state().histogram_large,
            "clic sur le badge du plein écran"
        );
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        assert!(h.state().histogram, "histogramme affiché par défaut");
        press(&mut h, Key::I, Modifiers::NONE);
        assert!(!h.state().histogram, "i le masque");
        leader(
            &mut h,
            &[(Key::I, Modifiers::NONE), (Key::S, Modifiers::NONE)],
        );
        assert_eq!(
            h.state().histogram_scale,
            HistogramScale::Linear,
            "<leader> i s : linéaire"
        );
        assert!(!h.state().clipping);
        press(&mut h, Key::W, Modifiers::NONE);
        assert!(h.state().clipping, "w : zones");
        // Masque calculé en fond : deux images ne suffisaient pas toujours (CI Windows).
        run_until(&mut h, |app| app.mask_textures.contains(&white_path));
        // <leader> i c : canal rouge (le grand histogramme reste fermé ; Maj+I l'ouvre), image d'analyse ; puis
        // vert, bleu, luminance, tous ; Échap ferme.
        leader(
            &mut h,
            &[(Key::I, Modifiers::NONE), (Key::C, Modifiers::NONE)],
        );
        assert!(
            !h.state().histogram_large,
            "<leader> i c : le canal change, le grand histogramme reste fermé"
        );
        press(&mut h, Key::I, Modifiers::SHIFT);
        assert!(h.state().histogram_large, "Maj+I l'ouvre");
        assert_eq!(h.state().histogram_channel, Some(0));
        // L'image d'analyse de tous les canaux peut encore être là (CI macOS) : attendre
        // celle du rouge.
        run_until(&mut h, |app| {
            app.analysis_texture
                .as_ref()
                .is_some_and(|t| t.0.1 == Some(0))
        });
        assert_eq!(
            h.state().analysis_texture.as_ref().unwrap().0,
            (white_path.clone(), Some(0))
        );
        let luminance = Some(tri::exposure::LUMINANCE);
        for expected in [Some(1), Some(2), luminance, None] {
            leader(
                &mut h,
                &[(Key::I, Modifiers::NONE), (Key::C, Modifiers::NONE)],
            );
            assert_eq!(h.state().histogram_channel, expected);
        }
        // r, g, b, a : un canal, ou tous ; b ne change pas la source, g ne commence pas gg.
        let source = h.state().source;
        for (key, expected) in [
            (Key::G, Some(1)),
            (Key::B, Some(2)),
            (Key::R, Some(0)),
            (Key::A, None),
        ] {
            press(&mut h, key, Modifiers::NONE);
            assert_eq!(h.state().histogram_channel, expected, "{key:?}");
        }
        assert_eq!(h.state().source, source);
        assert!(h.state().histogram_large, "reste ouvert");
        // Tableau : la ligne Luminance seulement quand la luminance est choisie, comme
        // sa courbe (retour du 28/10/2026).
        h.run_steps(2);
        assert!(h.query_by_label("Rouge").is_some());
        assert!(h.query_by_label("Luminance").is_none(), "tous les canaux");
        press(&mut h, Key::L, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.query_by_label("Luminance").is_some(), "l");
        assert!(h.query_by_label("Rouge").is_none());
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(!h.state().histogram_large);
    }

    #[test]
    fn dialogs_show_a_hand_over_checkboxes_and_grab_elsewhere() {
        let (mut h, dir) = harness();
        // Les cases du panneau de droite ne gênent pas la recherche de celle de la boîte.
        h.state_mut().metadata_panel = false;
        h.run_steps(3);
        h.state_mut().config_path = Some(dir.path().join("config.toml"));
        press(&mut h, Key::Comma, Modifiers::CTRL);
        // Une case à cocher (réglage booléen) : pas un bouton d'egui.
        h.event(UiEvent::Text("auto_advance".into()));
        h.run_steps(2);
        // La première de la fenêtre : `[gui] auto_advance` (la recherche floue en trouve
        // d'autres, dont le texte contient ces lettres dans l'ordre) ; pas la case
        // « Sous-dossiers » du panneau des dossiers, derrière.
        let panel = h.state().gui.folders.width;
        let rect = h
            .query_all_by_role(egui::accesskit::Role::CheckBox)
            .map(|n| n.rect())
            .find(|r| r.left() > panel)
            .expect("une case");
        // On a tapé : pointeur masqué jusqu'à ce que la souris bouge.
        h.hover_at(rect.center() + vec2(1.0, 0.0));
        h.run_steps(1);
        h.hover_at(rect.center());
        h.run_steps(2);
        assert_eq!(
            h.output().platform_output.cursor_icon,
            egui::CursorIcon::PointingHand,
            "main sur la case"
        );
        // Le titre de la boîte : on peut la déplacer.
        let title = h.get_by_label("Réglages").rect();
        h.hover_at(title.center());
        h.run_steps(2);
        assert_eq!(
            h.output().platform_output.cursor_icon,
            egui::CursorIcon::Grab
        );
    }

    #[test]
    fn the_cache_section_shows_its_size_and_clears_it_after_confirmation() {
        // Issue n° 128 : en tête de la section « Cache », la place par niveau, « Tout
        // vider » confirmé, en fond (cache du harnais : un dossier temporaire).
        let (mut h, dir) = harness();
        let cache = h.state().engine.as_ref().unwrap().cache.clone();
        let thumbnails = |c: &tri::cache::Cache| {
            c.usage(tri::cache::Level::Thumbnail)
                .map_or(0, |u| u.entries)
        };
        run_until(&mut h, |_| thumbnails(&cache) > 0);
        h.state_mut().config_path = Some(dir.path().join("config.toml"));
        press(&mut h, Key::Comma, Modifiers::CTRL);
        h.state_mut()
            .settings_window
            .as_mut()
            .unwrap()
            .show_section("cache");
        h.run_steps(3);
        assert!(h.query_by_label(&t!("cache-row-full")).is_some());
        h.get_by_label(&t!("cache-clear-all")).click();
        h.run_steps(2);
        // À sa place : « Vider » (confirmer) et « Annuler ».
        assert!(h.query_by_label(&t!("cache-clear-all")).is_none());
        h.get_by_label(&t!("cache-clear-cancel")).click();
        h.run_steps(2);
        h.get_by_label(&t!("cache-clear-all")).click();
        h.run_steps(2);
        // Le bouton de confirmation : le dernier « Vider » (sur la ligne du total).
        h.query_all_by_label(&t!("cache-clear-confirm"))
            .max_by(|a, b| a.rect().top().total_cmp(&b.rect().top()))
            .unwrap()
            .click();
        let tail = t!("cache-freed", size = "§");
        let tail = tail.split('§').next_back().unwrap().to_string();
        let freed = |h: &Harness<'_, TriApp>| h.query_by_label_contains(&tail).is_some();
        for _ in 0..400 {
            h.run_steps(1);
            if freed(&h) {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        assert!(freed(&h), "freed space announced");
        assert_eq!(thumbnails(&cache), 0);
    }

