    #[test]
    fn background_tasks_share_one_bar() {
        // Issue n° 36 : plusieurs tâches, une barre globale en bas du panneau des
        // métadonnées ; un clic déplie le détail. Panneau masqué : dans la barre d'état.
        let (mut h, _dir) = harness();
        run_until(&mut h, |app| {
            app.engine
                .as_ref()
                .unwrap()
                .scheduler
                .wait_idle(Duration::ZERO)
        });
        h.run_steps(3);
        let app = h.state_mut();
        app.gui.progress_hide_done = true;
        app.progress_hidden_until = None;
        app.progress[0] = Progress { done: 1, total: 4 };
        app.progress[3] = Progress { done: 3, total: 4 };
        h.run_steps(2);
        let global = t!("tasks-global", n = 2, percent = "50");
        assert!(
            h.query_by_label_contains(&global).is_some(),
            "une barre globale"
        );
        assert!(h.query_by_label_contains("1/4").is_none(), "détail replié");
        let folded = h.state().tasks_height;
        assert!(folded > 0.0, "panneau des tâches");
        h.get_by_label_contains(&global).click();
        h.run_steps(3);
        assert!(h.state().tasks_open);
        assert!(h.query_by_label_contains("1/4").is_some(), "détail déplié");
        // La fine barre reste à sa place : un second clic replie (retour du 25/10/2026).
        h.get_by_label_contains(&global).click();
        h.run_steps(3);
        assert!(!h.state().tasks_open);
        assert!(
            h.query_by_label_contains("1/4").is_none(),
            "replié de nouveau"
        );
        // Sa hauteur d'avant : pas un grand fond vide au-dessus de la barre (#158).
        assert_eq!(h.state().tasks_height, folded);
        // Panneau des métadonnées masqué : la barre globale passe dans la barre d'état.
        h.state_mut().metadata_panel = false;
        h.run_steps(3);
        assert!(h.query_by_label_contains(&global).is_some());
    }

    #[test]
    fn the_star_filter_compares_at_least_exactly_or_at_most() {
        // #165 : pas seulement « au moins » ; `f =` ou le bouton ≥ / = / ≤.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        for (i, key) in [Key::Num3, Key::Num4, Key::Num5].into_iter().enumerate() {
            h.state_mut().select(i);
            press(&mut h, key, Modifiers::NONE);
        }
        let count = |h: &Harness<'_, TriApp>| h.state().files.len();
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::Num4, Modifiers::NONE);
        assert_eq!(count(&h), 2, "au moins 4");
        press(&mut h, Key::F, Modifiers::NONE);
        type_text(&mut h, "=");
        assert_eq!(count(&h), 1, "exactement 4");
        assert!(h.state().filter_summary().contains("exactement 4"));
        h.get_by_label("=").click();
        h.run_steps(2);
        assert_eq!(count(&h), 2, "au plus 4");
        assert!(h.state().filter_summary().contains("4 étoiles ou moins"));
        h.get_by_label("≤").click();
        h.run_steps(2);
        assert_eq!(h.state().stars_op, tri::notes::StarsOp::AtLeast);
        assert_eq!(count(&h), 2, "au moins 4, de nouveau");
    }

