    #[test]
    fn the_next_card_goes_to_the_same_session() {
        // Issue n° 37 : la boîte restée sur le bilan, une nouvelle carte branchée : elle
        // repart sur cette carte, vers le même dossier de séance.
        let (mut h, dir) = harness();
        let card = |name: &str, image: &str| {
            let card = dir.path().join(name);
            std::fs::create_dir_all(card.join("DCIM")).unwrap();
            image::RgbImage::new(16, 16)
                .save(card.join("DCIM").join(image))
                .unwrap();
            tri::places::Place {
                name: name.into(),
                path: card,
                kind: tri::places::PlaceKind::Volume,
            }
        };
        let (first, second) = (card("CARTE1", "A.jpg"), card("CARTE2", "B.jpg"));
        h.state_mut().tree = Tree::with_places(vec![first.clone()], false);
        h.state_mut().settings.offload.open_after = false;
        h.run_steps(2);
        h.get_by_label("Décharger la carte…").click();
        let wait_for = |h: &mut Harness<'_, TriApp>, text: &str| {
            let deadline = Instant::now() + Duration::from_secs(20);
            while h.query_by_label_contains(text).is_none() {
                assert!(Instant::now() < deadline, "jamais vu : {text}");
                h.run_steps(1);
                std::thread::sleep(Duration::from_millis(10));
            }
        };
        wait_for(&mut h, "1 à copier");
        h.get_by_label("Décharger").click();
        wait_for(&mut h, "1 fichiers copiés et vérifiés");
        let session = h.state().offload.as_ref().unwrap().destination().unwrap();
        // CARTE2 arrive : la boîte repart sur elle, même séance proposée.
        let ctx = h.ctx.clone();
        h.state_mut().set_volumes(&ctx, vec![first, second.clone()]);
        assert_eq!(h.state().offload.as_ref().unwrap().source(), second.path);
        wait_for(&mut h, "1 à copier");
        h.get_by_label("Décharger").click();
        wait_for(&mut h, "1 fichiers copiés et vérifiés");
        assert!(session.join("A.jpg").is_file() && session.join("B.jpg").is_file());
    }

    #[test]
    fn the_next_card_comes_after_closing_even_at_the_same_path() {
        // Retour du 25/10/2026 (#37) : bilan refermé (ou copie en arrière-plan), et la
        // carte suivante montée au même chemin (deux cartes du même boîtier) : la boîte
        // s'ouvre quand même sur elle, vers la même séance.
        let (mut h, dir) = harness();
        let path = dir.path().join("disk");
        std::fs::create_dir_all(path.join("DCIM")).unwrap();
        image::RgbImage::new(16, 16)
            .save(path.join("DCIM/A.jpg"))
            .unwrap();
        let card = tri::places::Place {
            name: "disk".into(),
            path: path.clone(),
            kind: tri::places::PlaceKind::Volume,
        };
        h.state_mut().tree = Tree::with_places(vec![card.clone()], false);
        h.state_mut().settings.offload.open_after = false;
        h.run_steps(2);
        h.get_by_label("Décharger la carte…").click();
        let wait_for = |h: &mut Harness<'_, TriApp>, text: &str| {
            let deadline = Instant::now() + Duration::from_secs(20);
            while h.query_by_label_contains(text).is_none() {
                assert!(Instant::now() < deadline, "jamais vu : {text}");
                h.run_steps(1);
                std::thread::sleep(Duration::from_millis(10));
            }
        };
        wait_for(&mut h, "1 à copier");
        h.get_by_label("Décharger").click();
        wait_for(&mut h, "1 fichiers copiés et vérifiés");
        let session = h.state().offload.as_ref().unwrap().destination().unwrap();
        h.get_by_label("Fermer").click();
        h.run_steps(2);
        assert!(h.state().offload.is_none());
        // La carte part, une autre arrive au même chemin.
        let ctx = h.ctx.clone();
        h.state_mut().set_volumes(&ctx, vec![]);
        std::fs::remove_file(path.join("DCIM/A.jpg")).unwrap();
        image::RgbImage::new(16, 16)
            .save(path.join("DCIM/B.jpg"))
            .unwrap();
        h.state_mut().set_volumes(&ctx, vec![card.clone()]);
        assert_eq!(h.state().offload.as_ref().unwrap().source(), path);
        wait_for(&mut h, "1 à copier");
        h.get_by_label("Décharger").click();
        wait_for(&mut h, "1 fichiers copiés et vérifiés");
        assert!(session.join("A.jpg").is_file() && session.join("B.jpg").is_file());
        // Refermée sans décharger : plus de carte suivante proposée.
        h.get_by_label("Fermer").click();
        h.run_steps(2);
        h.state_mut().set_volumes(&ctx, vec![]);
        h.state_mut().set_volumes(&ctx, vec![card.clone()]);
        wait_for(&mut h, "0 à copier");
        h.get_by_label("Annuler").click();
        h.run_steps(2);
        assert!(h.state().offload.is_none());
        h.state_mut().set_volumes(&ctx, vec![]);
        h.state_mut().set_volumes(&ctx, vec![card]);
        assert!(h.state().offload.is_none(), "oubliée");
    }

    #[test]
    fn the_same_card_twice_counts_duplicates_in_the_chosen_folder() {
        let (mut h, dir) = harness();
        let card = dir.path().join("CARTE");
        std::fs::create_dir_all(card.join("DCIM")).unwrap();
        for i in 0..2 {
            image::RgbImage::new(16, 16)
                .save(card.join(format!("DCIM/IMG{i}.jpg")))
                .unwrap();
        }
        let place = tri::places::Place {
            name: "CARTE".into(),
            path: card.clone(),
            kind: tri::places::PlaceKind::Volume,
        };
        let wait_for = |h: &mut Harness<'_, TriApp>, text: &str| {
            let deadline = Instant::now() + Duration::from_secs(20);
            while h.query_by_label_contains(text).is_none() {
                assert!(Instant::now() < deadline, "jamais vu : {text}");
                h.run_steps(1);
                std::thread::sleep(Duration::from_millis(10));
            }
        };
        for round in 0..2 {
            h.state_mut().tree = Tree::with_places(vec![place.clone()], false);
            h.run_steps(2);
            h.get_by_label("Décharger la carte…").click();
            if round == 0 {
                wait_for(&mut h, "2 à copier");
                h.get_by_label("Décharger").click();
                wait_for(&mut h, "2 fichiers copiés et vérifiés");
                h.get_by_label("Fermer").click();
                h.run_steps(2);
            } else {
                // Même dossier de séance proposé : tout y est déjà.
                wait_for(&mut h, "2 déjà dans la destination ; 0 à copier");
                h.get_by_label("Annuler").click();
                h.run_steps(2);
            }
        }
    }

    #[test]
    fn a_copy_goes_on_in_the_background() {
        // Issue n° 72 : pendant une copie, « Continuer en arrière-plan » libère l'interface ;
        // la progression est dans la barre d'état, la fin y est annoncée.
        let (mut h, dir) = harness();
        let dest = dir.path().join("dest");
        std::fs::create_dir(&dest).unwrap();
        let image = h.state().files[0].path.clone();
        let (go, held) = mpsc::channel();
        let settings = h.state().settings.files.clone();
        // D'autres tâches (vignettes du dossier) peuvent tourner : détail des tâches
        // déplié, la copie y a toujours sa barre (#36).
        h.state_mut().tasks_open = true;
        h.state_mut().file_dialog = Some(crate::files::FileDialog::transfer_held(
            vec![image],
            &dest,
            &settings,
            held,
        ));
        h.run_steps(2);
        h.get_by_label(&t!("transfer-background")).click();
        h.run_steps(2);
        assert!(h.state().file_dialog.is_none(), "boîte libérée");
        assert_eq!(h.state().background_transfers.len(), 1);
        assert!(
            h.query_by_label_contains("copie vers").is_some(),
            "barre d'état"
        );
        // Clic sur la progression : la boîte revient, puis repart en arrière-plan.
        // Recliqué tant que la boîte n'est pas revenue (CI Windows : un clic juste après
        // l'apparition de la barre se perdait).
        let deadline = Instant::now() + Duration::from_secs(20);
        while h.state().file_dialog.is_none() {
            assert!(Instant::now() < deadline, "jamais réaffichée");
            h.get_by_label_contains("copie vers").click();
            h.run_steps(3);
        }
        while h.state().file_dialog.is_some() {
            assert!(Instant::now() < deadline, "jamais remise en arrière-plan");
            h.get_by_label(&t!("transfer-background")).click();
            h.run_steps(2);
        }
        go.send(()).unwrap();
        run_until(&mut h, |app| app.background_transfers.is_empty());
        assert!(dest.join("img0.jpg").is_file());
        assert_eq!(
            h.state().notice.as_ref().map(|(text, _)| text.clone()),
            Some(t!("transfer-done"))
        );
    }

    #[test]
    fn an_offload_in_the_background_offers_the_session_without_switching() {
        let (mut h, dir) = harness();
        let card = dir.path().join("CARTE");
        std::fs::create_dir_all(card.join("DCIM")).unwrap();
        image::RgbImage::new(16, 16)
            .save(card.join("DCIM/IMG0.jpg"))
            .unwrap();
        h.state_mut().tree = Tree::with_places(
            vec![tri::places::Place {
                name: "CARTE".into(),
                path: card,
                kind: tri::places::PlaceKind::Volume,
            }],
            false,
        );
        h.run_steps(2);
        let before = h.state().folder.dir.clone();
        h.get_by_label("Décharger la carte…").click();
        let deadline = Instant::now() + Duration::from_secs(20);
        while h.query_by_label("Décharger").is_none() {
            assert!(Instant::now() < deadline);
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
        h.get_by_label("Décharger").click();
        h.run_steps(1); // le clic démarre la copie
        assert!(h.state().offload.as_ref().unwrap().is_running());
        h.state_mut().offload.as_mut().unwrap().hide();
        // La copie se termine en fond : plus de boîte, séance proposée, dossier inchangé.
        while h.state().offload.is_some() {
            assert!(Instant::now() < deadline, "jamais terminé");
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
        h.run_steps(2);
        assert_eq!(
            h.state().folder.dir,
            before,
            "pas de changement de dossier d'office"
        );
        assert!(h.state().offloaded.is_some());
        assert!(
            h.query_by_label_contains("1 copiés").is_some(),
            "bilan dans la barre d'état"
        );
        // Aperçus de la séance calculés pendant la copie (issue n° 40), dossier pas ouvert :
        // le scheduler de la séance s'arrête une fois fini, la vignette est en cache.
        while !h.state().session_previews.is_empty() {
            assert!(
                Instant::now() < deadline,
                "aperçus de la séance jamais finis"
            );
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
        let session = h.state().offloaded.clone().unwrap();
        let engine = h.state().engine.as_ref().unwrap();
        let copy = MediaFile {
            path: session.join("IMG0.jpg"),
            kind: MediaKind::Flat,
        };
        let key = preview::key(&copy, Level::Thumbnail, &engine.preview).unwrap();
        assert!(
            engine.cache.contains(&key),
            "vignette calculée sans ouvrir la séance"
        );
        // Recliqué tant que la séance n'est pas ouverte (CI Linux : le clic, à côté du bilan
        // qui venait de s'afficher, se perdait parfois).
        while h.state().folder.dir == before {
            assert!(
                Instant::now() < deadline,
                "séance jamais ouverte à la demande"
            );
            h.get_by_label_contains("Ouvrir la séance").click();
            h.run_steps(3);
        }
        assert_eq!(names(&h), ["IMG0.jpg"]);
        assert!(h.state().offloaded.is_none());
    }

