    #[test]
    fn presets_set_ratio_name_and_profile_and_new_ones_are_saved() {
        let (mut h, dir) = harness();
        let config = dir.path().join("config.toml");
        h.state_mut().config_path = Some(config.clone());
        h.run_steps(3);
        let image = h.state().files[0].path.clone();
        press(&mut h, Key::V, Modifiers::NONE);
        run_until(&mut h, |app| {
            app.crop.as_ref().is_some_and(crate::crop::Crop::ready)
        });
        // Tab : premier préréglage, « Story » (9:16, Web) ; Tab puis Maj+Tab y revient. Pas
        // de champ pris par Tab (déplacement du focus d'egui).
        press(&mut h, Key::Tab, Modifiers::NONE);
        assert!(
            !h.ctx.egui_wants_keyboard_input(),
            "Tab ne va pas dans le champ du nom"
        );
        let first = h.state().crop.as_ref().unwrap().preset.clone();
        press(&mut h, Key::Tab, Modifiers::NONE);
        assert_ne!(h.state().crop.as_ref().unwrap().preset, first);
        press(&mut h, Key::Tab, Modifiers::SHIFT);
        assert_eq!(h.state().crop.as_ref().unwrap().preset, first);
        // p : la carte de netteté, pas un préréglage.
        let peaking = h.state().peaking;
        press(&mut h, Key::P, Modifiers::NONE);
        assert_ne!(h.state().peaking, peaking);
        assert_eq!(h.state().crop.as_ref().unwrap().preset, first);
        let crop = h.state().crop.as_ref().unwrap();
        assert_eq!(crop.ratio, tri::versions::Ratio::Fixed(9, 16));
        assert_eq!(crop.name, "Story");
        assert_eq!(crop.profile.as_deref(), Some("web"));
        // Enregistrer comme préréglage : écrit dans le fichier, identifiant libre.
        h.get_by_label(&t!("crop-preset-save")).click();
        h.run_steps(2);
        let text = std::fs::read_to_string(&config).unwrap();
        assert!(text.contains("[versions.presets.story-2]"), "{text}");
        assert!(
            text.contains("name = \"Story (2)\""),
            "nom pas en double : {text}"
        );
        assert!(text.contains("ratio = \"9:16\""), "{text}");
        assert_eq!(
            h.state().settings.versions.presets.0.len(),
            3,
            "appliqué à chaud"
        );
        // Entrée : la version prend le nom et le profil du préréglage.
        press(&mut h, Key::Enter, Modifiers::NONE);
        let saved = tri::versions::read(&image).unwrap();
        assert_eq!(saved.list[0].name, "Story");
        assert_eq!(saved.list[0].profile.as_deref(), Some("web"));
        // Issue n° 14 : pas deux versions du même nom. Le préréglage propose « Story (2) » ;
        // un nom tapé déjà pris (casse comprise) n'est pas enregistré, le recadrage reste.
        press(&mut h, Key::V, Modifiers::NONE);
        run_until(&mut h, |app| {
            app.crop.as_ref().is_some_and(crate::crop::Crop::ready)
        });
        press(&mut h, Key::Tab, Modifiers::NONE);
        assert_eq!(h.state().crop.as_ref().unwrap().name, "Story (2)");
        h.state_mut().crop.as_mut().unwrap().name = "story ".into();
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert!(h.state().crop.is_some(), "refusée, recadrage gardé");
        assert!(h.state().notice.as_ref().is_some_and(|(_, error)| *error));
        assert_eq!(tri::versions::read(&image).unwrap().list.len(), 1);
        h.state_mut().crop.as_mut().unwrap().name = "Story bis".into();
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert!(h.state().crop.is_none());
        let names: Vec<String> = tri::versions::read(&image)
            .unwrap()
            .list
            .into_iter()
            .map(|v| v.name)
            .collect();
        assert_eq!(names, ["Story", "Story bis"]);
        // Reprendre une version : elle garde son nom, mais pas celui de l'autre.
        h.state_mut().edit_version(&image, 1);
        assert!(h.state().crop.as_ref().unwrap().name_ok());
        h.state_mut().crop.as_mut().unwrap().name = "Story".into();
        assert!(h.state().crop.as_ref().unwrap().name_taken());
    }

    #[test]
    fn export_profiles_follow_the_arrows_with_a_multiple_selection() {
        // Assez d'images pour que la grille défile (comme un vrai dossier de 472 images).
        let names: Vec<String> = (0..80).map(|i| format!("img{i:02}.jpg")).collect();
        let names: Vec<&str> = names.iter().map(String::as_str).collect();
        let (mut h, _dir) = harness_files(&names, 32, 24);
        h.run_steps(3);
        // Deux images sélectionnées (Espace), puis Ctrl+E.
        press(&mut h, Key::Space, Modifiers::NONE);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        press(&mut h, Key::Space, Modifiers::NONE);
        assert_eq!(h.state().selection.visible(&h.state().files), 2);
        press(&mut h, Key::E, Modifiers::CTRL);
        let choice = |h: &Harness<'_, TriApp>| match &h.state().file_dialog {
            Some(crate::files::FileDialog::Export(d)) => d.choice(),
            _ => panic!("boîte d'export attendue"),
        };
        let first = choice(&h);
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        assert_eq!(choice(&h), first + 1, "flèche bas : profil suivant");
        press(&mut h, Key::ArrowUp, Modifiers::NONE);
        assert_eq!(choice(&h), first);
        assert_eq!(
            h.state().selection.visible(&h.state().files),
            2,
            "sélection gardée"
        );
        // Un clic dans la boîte (ici sur son titre, au-dessus de la grille) ne vide pas la
        // sélection.
        h.get_by_label_contains("Exporter 2 images").click();
        h.run_steps(2);
        assert_eq!(
            h.state().selection.visible(&h.state().files),
            2,
            "clic dans la boîte"
        );
    }

    #[test]
    fn an_image_is_developed_with_the_chosen_software() {
        // 26/10/2026 : <leader>d / <leader>p, ou « Développer avec » au clic droit ; le
        // choix passe devant le logiciel du développement, le temps de la session.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        // RapidRAW pas installé : on le dit.
        h.state_mut().developers = fake_darktable();
        // Une seule liste déroulante, celle de la boîte (le panneau de droite a celle de
        // l'ordre).
        h.state_mut().filter_bar = false;
        h.state_mut().metadata_panel = false;
        let lead = |h: &mut Harness<'_, TriApp>| press(h, Key::B, Modifiers::CTRL);
        lead(&mut h);
        press(&mut h, Key::R, Modifiers::NONE);
        press(&mut h, Key::P, Modifiers::NONE);
        let (text, error) = h.state().notice.clone().expect("message");
        assert!(error && text.contains("RapidRAW"), "{text}");
        assert!(h.state().develop_choice.is_empty());
        // darktable installé mais rien développé : refusé aussi (décidé le 31/10/2026 au
        // soir : tous les logiciels, pas seulement RapidRAW ; seul LibRaw est toujours là).
        lead(&mut h);
        press(&mut h, Key::R, Modifiers::NONE);
        press(&mut h, Key::D, Modifiers::NONE);
        let (text, error) = h.state().notice.clone().expect("message");
        assert!(error && text.contains("Darktable"), "{text}");
        assert!(h.state().develop_choice.is_empty());
        assert_eq!(h.state().mode, Mode::Grid);
        // Les deux premières images développées dans darktable (historique non vide) ;
        // l'absence du sidecar vient d'être mémorisée (`cache::stamp`) : oubliée.
        let mut sidecars = Vec::new();
        for i in 0..2 {
            let path = h.state().files[i].path.clone();
            let name = path.file_name().unwrap().to_string_lossy().to_string();
            let sidecar = path.with_file_name(format!("{name}.xmp"));
            std::fs::write(&sidecar, r#"<rdf:Description darktable:history_end="3"/>"#).unwrap();
            sidecars.push(sidecar);
        }
        tri::cache::forget_stamps(sidecars.iter().map(|p| p.as_path()));
        // darktable : choisi pour l'image, rendu demandé, source « développé ».
        lead(&mut h);
        press(&mut h, Key::R, Modifiers::NONE);
        press(&mut h, Key::D, Modifiers::NONE);
        let path = h.state().files[0].path.clone();
        assert_eq!(
            h.state().develop_choice.get(&path),
            Some(&tri::develop::Engine::Darktable)
        );
        assert_eq!(h.state().source, Source::Developed);
        assert_eq!(h.state().mode, Mode::View);
        // Clic droit sur une autre image : la liste « Développer avec ».
        press(&mut h, Key::Escape, Modifiers::NONE);
        let other = h.state().files[1].path.clone();
        h.state_mut().rating_dialog = Some((other.clone(), pos2(200.0, 200.0)));
        h.run_steps(2);
        h.get_by_role(egui::accesskit::Role::ComboBox).click();
        h.run_steps(2);
        h.get_by_label("Darktable").click();
        h.run_steps(2);
        assert_eq!(h.state().selected, 1, "l'image du clic droit");
        assert_eq!(
            h.state().develop_choice.get(&other),
            Some(&tri::develop::Engine::Darktable)
        );
        assert!(h.state().rating_dialog.is_none());
        // La troisième, sans développement : « Darktable » grisé dans sa liste, le rendu
        // LibRaw reste proposé.
        press(&mut h, Key::Escape, Modifiers::NONE);
        let third = h.state().files[2].path.clone();
        h.state_mut().rating_dialog = Some((third.clone(), pos2(200.0, 200.0)));
        h.run_steps(2);
        h.get_by_role(egui::accesskit::Role::ComboBox).click();
        h.run_steps(2);
        h.get_by_label("Darktable").click();
        h.run_steps(2);
        assert!(
            !h.state().develop_choice.contains_key(&third),
            "grisé : sans effet"
        );
        assert!(h.state().rating_dialog.is_some(), "la boîte reste ouverte");
        // La liste s'est refermée sur le clic : rouverte pour le rendu LibRaw.
        h.get_by_role(egui::accesskit::Role::ComboBox).click();
        h.run_steps(2);
        h.get_by_label(&t!("develop-with-libraw")).click();
        h.run_steps(2);
        assert!(h.state().rating_dialog.is_none());
    }

    #[test]
    fn r_goes_through_every_render_of_the_list() {
        // #114, revu le 06/11/2026 : `r` fait le tour du rendu affiché (pour tout le
        // dossier) : couverture, chaque logiciel, rendu RAW, JPEG boîtier.
        use tri::develop::Engine;
        let (mut h, _dir) = harness();
        h.run_steps(3);
        h.state_mut().developers = fake_darktable().with(Arc::new(FakeDeveloper(Engine::RapidRaw)));
        let file = h.state().files[0].clone();
        let name = file.path.file_name().unwrap().to_string_lossy().to_string();
        std::fs::write(
            file.path.with_file_name(format!("{name}.xmp")),
            r#"<rdf:Description darktable:history_end="3"/>"#,
        )
        .unwrap();
        std::fs::write(
            file.path.with_file_name(format!("{name}.rrdata")),
            r#"{"adjustments": {"exposure": 1}}"#,
        )
        .unwrap();
        // Le sidecar darktable nettement plus ancien (précision des dates selon le système).
        std::fs::File::options()
            .write(true)
            .open(file.path.with_file_name(format!("{name}.xmp")))
            .unwrap()
            .set_modified(std::time::SystemTime::now() - Duration::from_secs(60))
            .unwrap();
        {
            let engine = h.state().engine.as_ref().unwrap();
            let bitmap = tri::bitmap::Bitmap {
                width: 8,
                height: 6,
                data: vec![100; 8 * 6 * 3],
            };
            for e in [Engine::Darktable, Engine::RapidRaw] {
                let key = preview::key(&file, Level::Developed(e), &engine.preview).unwrap();
                engine.cache.put(&key, &bitmap).unwrap();
            }
        }
        press(&mut h, Key::Enter, Modifiers::NONE);
        let b = |h: &mut Harness<'_, TriApp>| {
            press(h, Key::R, Modifiers::NONE);
            (h.state().source, h.state().developed_level_at(0))
        };
        // La couverture : le développement le plus récent (le .rrdata).
        assert_eq!(
            b(&mut h),
            (Source::Developed, Some(Level::Developed(Engine::RapidRaw)))
        );
        assert_eq!(
            b(&mut h),
            (Source::Developed, Some(Level::Developed(Engine::Darktable)))
        );
        assert_eq!(
            b(&mut h),
            (Source::Developed, Some(Level::Developed(Engine::RapidRaw)))
        );
        assert_eq!(b(&mut h).0, Source::Raw);
        assert_eq!(b(&mut h).0, Source::Embedded);
        // `r` dit le rendu choisi.
        let notice = h.state().notice.clone().map(|(n, _)| n).unwrap_or_default();
        assert!(notice.contains(&t!("grid-render-jpeg")), "{notice}");
    }

    #[test]
    fn switching_software_is_not_a_stale_development() {
        // Essai du 26/10/2026 : <leader>p sur une image déjà développée dans darktable
        // disait « Développement modifié dans darktable ». Changer de logiciel n'est pas
        // un développement périmé ; un vrai périmé nomme son logiciel.
        use tri::develop::Engine;
        let (mut h, _dir) = harness();
        h.run_steps(3);
        h.state_mut().developers = fake_darktable().with(Arc::new(FakeDeveloper(Engine::RapidRaw)));
        let path = h.state().files[0].path.clone();
        h.state_mut().status[0].developed = Avail::Ready;
        h.state_mut().notice = None;
        h.state_mut().choose_developer(&path, Engine::RapidRaw);
        h.state_mut().developed_ready(0);
        assert!(h.state().notice.is_none(), "{:?}", h.state().notice);
        // Prêt pour RapidRAW, puis plus dans le cache : périmé, dans RapidRAW.
        h.state_mut().status[0].developed = Avail::Ready;
        h.state_mut().developed_ready(0);
        let (text, _) = h.state().notice.clone().expect("message");
        assert!(text.contains("RapidRAW"), "{text}");
    }

