        std::fs::write(&sidecar, r#"<rdf:Description darktable:history_end="3"/>"#).unwrap();
        // Comme la surveillance du dossier : le relevé du sidecar est à refaire.
        tri::cache::forget_stamps([sidecar.as_path()]);
